763	/// The text of `job`'s block: from its `  <job>:` line to the next job's.
764	fn job<'a>(workflow: &'a str, job: &str) -> &'a str {
765	    let start = workflow
766	        .find(&format!("\n  {job}:\n"))
767	        .unwrap_or_else(|| panic!("no job `{job}`"))
768	        + 1;
769	    let rest = &workflow[start..];
770	    let end = rest
771	        .match_indices("\n  ")
772	        .find(|(index, _)| !rest[index + 3..].starts_with(' '))
773	        .map_or(rest.len(), |(index, _)| index);
774	    &rest[..end]
775	}
