541	                return Err(GraphError::ReleaseInvariant {
542	                    detail: format!("forge publish `{:?}` has no prepared draft release", operation.id()),
543	                })
544	            }
545	        };
546	        prepared.insert(
547	            operation.id().clone(),
548	            PreparedOperation::ForgePublish(ForgePublishOperation {
549	                tag,
550	                prerelease: version.is_prerelease(),
551	            }),
552	        );
553	        operations.insert(operation.id().clone(), operation);
554	    }
555	
556	    Ok((
557	        ReleaseInputSnapshotV1::new(source, package_inputs)?,
558	        canonical_operation_order(operations)?,
