566	/// through a runtime, optional, or peer edge must be selected with it, or the
567	/// selected package would publish pointing at a version that does not exist.
568	/// Standalone npm platform packages are one case of this.
569	fn require_dependencies_selected<R: CommandRunner, D: DependencyResolver>(
