        std::fs::write(path, body).unwrap();
    };
    write("pnpm-workspace.yaml", "packages:\n  - \"packages/*\"\n");
    write("pnpm-lock.yaml", "lockfileVersion: '9.0'\n");
    write(
        "packages/cli/package.json",
