}

#[test]
fn a_product_without_its_artifact_owner_cannot_derive_slots() {
    let dir = product_and_plugin_repo("1.0.0", "2.0.0");
    let error = derive_with_artifact_policy(&dir, &cargo_release(&["core"])).unwrap_err();
    assert!(
