    let git = GitAccess::new(root, &callisto_fixtures::git::GitRunner);
    git.create_tag(
        name,
        &target,
        Some(message),
        TagSignPolicy::ForceUnsigned,
        &callisto_model::ApplyPermit::force_for_tests(),
    )
    .unwrap();
    TagOperation {
        name: TagName::new_unchecked(name.to_owned()),
        target,
        annotation: message.to_owned(),
    }
}

