421	/// Only npm's own `E404` code proves absence, never text around it; any other failure is a retried `CommandFailed`.
422	fn classify_npm_view(output: &CommandOutput, version: &Version) -> Attempt<ProviderObservationV1> {
423	    if output.success() {
424	        return if output.stdout_trimmed().is_empty() {
425	            transient(ProviderIndeterminateCause::MalformedResponse, None)
426	        } else {
