455	    stderr.lines().find_map(|line| {
456	        let rest = line
457	            .strip_prefix("npm ERR! ")
458	            .or_else(|| line.strip_prefix("npm error "))?;
459	        rest.strip_prefix("code ").map(|code| code.trim().to_owned())
