535	/// PyPI's own PEP 691 JSON simple index, not `pip`: `pip index versions` is
536	/// experimental and hides yanked releases, and an unreachable index and a
537	/// missing project both look like "no versions found" to it. The index itself
538	/// answers plainly -- 200 with a `files[]` entry naming the version, or 404 --
539	/// so observation goes straight to `https://pypi.org/simple/<project>/`
540	/// (or the configured private index) over `curl`, never through `pip`.
541	const PYPI_DEFAULT_SIMPLE_INDEX: &str = "https://pypi.org/simple";
542	
543	/// PEP 691: the versioned JSON media type, so the index cannot fall back to
544	/// the legacy HTML page a bare GET would otherwise serve.
545	const PYPI_SIMPLE_ACCEPT: &str = "application/vnd.pypi.simple.v1+json";
546	
547	/// The project's simple-index URL: the configured private index if one is
548	/// bound (already https-validated in `binding.rs`), else the public default.
549	fn pypi_simple_index_url(endpoint: Option<&str>, package_name: &str) -> String {
550	    let base = endpoint.unwrap_or(PYPI_DEFAULT_SIMPLE_INDEX);
551	    let project = normalize_pypi_project_name(package_name);
552	    format!("{}/{project}/", base.trim_end_matches('/'))
553	}
554	
555	/// One file entry of a PEP 691 JSON simple-index response -- only the fields
556	/// the observation reads.
557	#[derive(serde::Deserialize)]
558	struct PypiSimpleFile {
559	    filename: String,
560	    /// `false` when not yanked, or a (possibly empty) reason string when it is.
561	    #[serde(default)]
562	    yanked: Option<serde_json::Value>,
563	}
564	
565	#[derive(serde::Deserialize)]
566	struct PypiSimpleIndex {
567	    files: Vec<PypiSimpleFile>,
568	}
569	
570	impl PypiSimpleFile {
571	    fn is_yanked(&self) -> bool {
572	        !matches!(self.yanked, None | Some(serde_json::Value::Bool(false)))
573	    }
574	}
575	
576	/// The version segment of a simple-index filename, or `None` for an extension
577	/// this parser does not recognize (a legacy installer, say).
578	///
579	/// A wheel's distribution segment is PEP 427-escaped to underscores only, so
580	/// splitting on `-` unambiguously yields `version` second. A PEP 440 version
581	/// never itself contains a hyphen, so an sdist's *last* `-` is always the
582	/// name/version boundary regardless of how the distribution name is spelled.
583	fn pypi_simple_file_version(filename: &str) -> Option<&str> {
584	    if let Some(stem) = filename.strip_suffix(".whl") {
585	        return stem.split('-').nth(1);
586	    }
587	    [".tar.gz", ".tar.bz2", ".tar.xz", ".tar.Z", ".zip"]
588	        .into_iter()
589	        .find_map(|ext| filename.strip_suffix(ext))
590	        .and_then(|stem| stem.rsplit_once('-'))
591	        .map(|(_, version)| version)
592	}
593	
594	/// Whether a simple-index file's filename names exactly the requested version.
595	fn pypi_simple_file_matches(file: &PypiSimpleFile, version: &Version) -> bool {
596	    pypi_simple_file_version(&file.filename).is_some_and(|candidate| {
597	        Version::parse(candidate, version.grammar())
598	            .is_ok_and(|candidate| candidate.compare(version) == Ok(std::cmp::Ordering::Equal))
599	    })
600	}
601	
602	/// Classifies a parsed 200 body: the matching file's yank status decides the
603	/// answer, mirroring cargo's yanked-is-absent rationale above -- a yanked
604	/// release is not the version this intent authorized, so it fails closed.
605	fn classify_pypi_simple_body(body: &str, version: &Version) -> Attempt<ProviderObservationV1> {
606	    let Ok(index) = serde_json::from_str::<PypiSimpleIndex>(body) else {
607	        return transient(ProviderIndeterminateCause::MalformedResponse, None);
608	    };
609	    let matching = index
610	        .files
611	        .iter()
612	        .filter(|file| pypi_simple_file_matches(file, version));
613	    let mut matched = false;
614	    for file in matching {
615	        if file.is_yanked() {
616	            return settled(ProviderObservationV1::Absent);
617	        }
618	        matched = true;
619	    }
620	    if !matched {
621	        return settled(ProviderObservationV1::Absent);
622	    }
623	    settled(ProviderObservationV1::Exact {
624	        evidence: ProviderEvidenceV1::RegistryVersion {
625	            version: version.clone(),
626	            checksum: None,
627	            yanked: Some(false),
628	        },
629	    })
630	}
631	
632	/// Classifies one `curl -sS -i` run against the simple index. A private index
633	/// that ignores `Accept` and serves its legacy HTML page fails the JSON parse
634	/// inside [`classify_pypi_simple_body`] and reads as `MalformedResponse`, same
635	/// as any other body PEP 691 JSON parsing cannot make sense of.
636	///
637	/// Any other status shares [`HttpResponse::is_transient`] with GitHub's `gh api` reads, so it retries on
638	/// `Retry-After` instead of settling immediately, and either way reports the status as `ProviderStatus`.
639	fn classify_pypi_simple(output: &CommandOutput, version: &Version) -> Attempt<ProviderObservationV1> {
640	    let response = match parse_http_response(&output.stdout) {
641	        Ok(response) => response,
642	        Err(_) if !output.success() => return transient(ProviderIndeterminateCause::CommandFailed, None),
643	        Err(_) => return transient(ProviderIndeterminateCause::MalformedResponse, None),
644	    };
645	    match response.status {
646	        200 => classify_pypi_simple_body(&response.body, version),
647	        404 => settled(ProviderObservationV1::Absent),
648	        status if response.is_transient() => transient(
649	            ProviderIndeterminateCause::ProviderStatus { status },
650	            response.retry_after(),
651	        ),
652	        status => settled(ProviderObservationV1::Indeterminate {
653	            cause: ProviderIndeterminateCause::ProviderStatus { status },
654	        }),
655	    }
656	}
