        ("my_pkg-1.0.0.tar.gz", "sdist"),
        ("my_pkg-1.0.1-py3-none-any.whl", "another version"),
        ("my_pkg-1.0.1.tar.gz", "another version"),
        ("other_pkg-1.0.0-py3-none-any.whl", "another package"),
