fn an_uploaded_file_without_an_index_digest_is_not_flagged() {
    let set = set();
    set.mark_uploaded(&[&set.files[0], &set.files[1]]);
    let held = [
        remote("my_pkg-1.0.0-py3-none-any.whl", None, false),
        remote("my_pkg-1.0.0.tar.gz", None, false),
