                    workflow_commit: orchestration_revision,
                    subject_digest: digest,
                    // Swapped: release source instead of the orchestration revision.
                    source_commit: release_source,
                },
            }],
        );
        assert!(matches!(result, Err(ArtifactManifestError::MismatchedAttestation)));
    }

    /// Two `ArtifactUpload` operations that share package/version/platform/asset_name
    /// but differ only in `attestation_policy` are distinct `ArtifactSlotId`s and must
    /// remain distinct `ReleaseOperationId`s under `Ord`, not just `Eq` -- otherwise
    /// `BTreeSet`/`BTreeMap` keys silently collapse them (the `a.cmp(b) == Equal implies
    /// a == b` invariant those collections require).
    #[test]
    fn artifact_upload_ids_differing_only_by_attestation_policy_stay_distinct_under_ord() {
        let package = ReleasePackageId::parse("cargo/demo").unwrap();
        let version = Version::semver(1, 0, 0);
        let slot_a = ArtifactSlotId::new(
            package.clone(),
            version.clone(),
            "x86_64-unknown-linux-gnu",
            "demo.tar.gz",
            GitHubRepository::parse("orin-dx/callisto").unwrap(),
            ".github/workflows/release.yml",
            CommitSha::parse(&"a".repeat(40)).unwrap(),
        )
        .unwrap();
        let slot_b = ArtifactSlotId::new(
            package,
            version,
            "x86_64-unknown-linux-gnu",
            "demo.tar.gz",
            GitHubRepository::parse("orin-dx/callisto").unwrap(),
            ".github/workflows/release.yml",
            CommitSha::parse(&"b".repeat(40)).unwrap(),
        )
        .unwrap();
        assert_ne!(slot_a, slot_b, "the two slots must differ only by attestation_policy");

        let id_a = ReleaseOperationId::artifact_upload(slot_a.clone());
        let id_b = ReleaseOperationId::artifact_upload(slot_b.clone());

        assert_ne!(id_a, id_b, "distinct attestation policies must stay Eq-distinct");
        assert_ne!(
            id_a.cmp(&id_b),
            Ordering::Equal,
            "distinct attestation policies must not compare Ord::Equal"
        );

        let mut ids = BTreeSet::new();
        assert!(ids.insert(id_a.clone()), "first id must insert");
        assert!(
            ids.insert(id_b.clone()),
            "second id must NOT be displaced by the first in a BTreeSet"
        );
        assert_eq!(ids.len(), 2);

        // Exercise the real ReleaseIntentV1::new / validate_operations path: this must
        // NOT be rejected as a duplicate operation.
        let op_a = ReleaseOperation::artifact_upload(slot_a.clone(), vec![]).unwrap();
        let op_b = ReleaseOperation::artifact_upload(slot_b.clone(), vec![]).unwrap();
        let (first, second) = if op_a.id() <= op_b.id() {
            (op_a, op_b)
        } else {
            (op_b, op_a)
        };
        let (first_slot, second_slot) = if first.id() == &id_a {
            (slot_a, slot_b)
        } else {
            (slot_b, slot_a)
        };
        let intent = test_intent_with_slots(
            ReleaseInputSnapshotV1::new(SourceIdentity::git_commit("d".repeat(40)).unwrap(), vec![]),
            ExecutionTrustProfileV1::GitCommit,
            vec![first, second],
            vec![first_slot, second_slot],
        );
        assert!(
            intent.is_ok(),
            "two artifact uploads differing only by attestation_policy must not collide: {intent:?}"
        );
    }

    /// Sibling instance of the same `.render()`-only defect, found in
    /// `ArtifactSlotId::cmp` (a different type in the same file) while
    /// auditing `ReleaseOperationId` above. Same construction: two slots
    /// identical in every field except `version.grammar()`.
    #[test]
    fn artifact_slot_ids_differing_only_by_version_grammar_stay_distinct_under_ord() {
        let package = ReleasePackageId::parse("cargo/demo").unwrap();
        let v_semver = Version::parse("1.2.3", VersionGrammar::SemVer).unwrap();
        let v_pep440 = Version::parse("1.2.3", VersionGrammar::Pep440).unwrap();
        assert_eq!(v_semver.render(), v_pep440.render());

        let slot_a = ArtifactSlotId::new(
            package.clone(),
            v_semver,
            "x86_64-unknown-linux-gnu",
            "demo.tar.gz",
            GitHubRepository::parse("orin-dx/callisto").unwrap(),
            ".github/workflows/release.yml",
            CommitSha::parse(&"a".repeat(40)).unwrap(),
        )
        .unwrap();
        let slot_b = ArtifactSlotId::new(
            package,
            v_pep440,
            "x86_64-unknown-linux-gnu",
            "demo.tar.gz",
            GitHubRepository::parse("orin-dx/callisto").unwrap(),
            ".github/workflows/release.yml",
            CommitSha::parse(&"a".repeat(40)).unwrap(),
        )
        .unwrap();

        assert_ne!(slot_a, slot_b, "distinct version grammars must stay Eq-distinct");
        assert_ne!(
            slot_a.cmp(&slot_b),
            Ordering::Equal,
            "distinct version grammars must not compare Ord::Equal"
        );

        let mut slots = BTreeSet::new();
        assert!(slots.insert(slot_a), "first slot must insert");
        assert!(
            slots.insert(slot_b),
            "second slot must NOT be displaced by the first in a BTreeSet"
        );
        assert_eq!(slots.len(), 2);
    }

    /// `.` names the directory an asset path is joined onto, not a file in it.
    #[test]
    fn artifact_slot_components_reject_dot_and_dot_dot() {
        let slot = |platform: &str, asset: &str| {
            ArtifactSlotId::new(
                ReleasePackageId::new(Ecosystem::Cargo, "demo").unwrap(),
                Version::semver(1, 0, 0),
                platform,
                asset,
                GitHubRepository::parse("orin-dx/callisto").unwrap(),
                ".github/workflows/release.yml",
                CommitSha::parse(&"b".repeat(40)).unwrap(),
            )
        };
        for (platform, asset) in [(".", "a.tar.gz"), ("linux", "."), ("..", "a.tar.gz"), ("linux", "..")] {
            assert!(
                matches!(slot(platform, asset), Err(ArtifactSlotError::UnsafeSlotComponent)),
                "unsafe slot component accepted: {platform:?}/{asset:?}"
            );
        }
        assert!(slot("x86_64-unknown-linux-gnu", "callisto.tar.gz").is_ok());
    }
}

//! Artifact-byte and GitHub-attestation verification for durable releases.
//!
//! A manifest is only a claim. This module verifies the actual on-disk bytes
//! and asks GitHub to validate the signing certificate against the policy
//! embedded in the immutable release intent before an executor can upload an
//! asset. It intentionally owns no upload side effect.

use std::{
    fs::{self, File},
    path::{Component, Path, PathBuf},
};

use callisto_model::{ArtifactManifestV1, CommandRunner, ReleaseIntentV1};

use crate::GraphError;

use super::release::provider::policy::{self, retry_observation, run_observation, Attempt};
use super::release::{programs, timeouts};

/// A manifest whose exact local bytes and GitHub provenance have been checked.
///
/// The constructor is private: callers can obtain this capability only with
/// [`verify_artifact_manifest`]. It borrows the manifest so an executor cannot
/// silently substitute a different manifest after verification.
#[derive(Debug)]
pub struct VerifiedArtifactManifest<'a> {
    manifest: &'a ArtifactManifestV1,
    root: PathBuf,
}

impl<'a> VerifiedArtifactManifest<'a> {
    pub fn manifest(&self) -> &'a ArtifactManifestV1 {
        self.manifest
    }

    /// Test-only pairing of a manifest with a root, for simulators whose
    /// providers issue no real upload and read no local asset bytes.
    #[cfg(test)]
    pub(crate) fn for_tests(manifest: &'a ArtifactManifestV1, root: PathBuf) -> Self {
        Self { manifest, root }
    }

    pub(crate) fn path_for(&self, slot: &callisto_model::ArtifactSlotId) -> Result<PathBuf, GraphError> {
        resolve_asset_path(&self.root, &slot.asset_name)
    }

    /// Returns the already intent-bound manifest entry for `slot`.
    pub(crate) fn entry_for(
        &self,
        slot: &callisto_model::ArtifactSlotId,
    ) -> Result<&callisto_model::ArtifactManifestEntryV1, GraphError> {
        self.manifest
            .entries
            .iter()
            .find(|entry| entry.slot == *slot)
            .ok_or_else(|| GraphError::ReleaseInvariant {
                detail: format!("verified artifact manifest has no entry for `{}`", slot.asset_name),
            })
    }
}

/// Verifies every manifest entry against the exact artifact directory.
///
/// The artifact directory and every candidate are canonicalized, and symbolic
/// links are rejected, so a manifest asset name cannot escape the supplied
/// build-output directory. Each asset is streamed once for a bounded-memory
/// SHA-256 and size comparison. `gh attestation verify` then validates the
/// repository, workflow path and commit, source commit, and hosted-runner
/// policy declared by the immutable artifact slot.
pub fn verify_artifact_manifest<'a, R: CommandRunner>(
    intent: &ReleaseIntentV1,
    manifest: &'a ArtifactManifestV1,
    artifact_root: &Path,
    runner: &R,
) -> Result<VerifiedArtifactManifest<'a>, GraphError> {
    manifest
        .validate_for_intent(intent)
        .map_err(|source| GraphError::ArtifactManifest { source })?;

    let root = canonical_artifact_root(artifact_root)?;
    for entry in &manifest.entries {
        let path = resolve_asset_path(&root, &entry.slot.asset_name)?;
        let file = File::open(&path).map_err(|error| GraphError::ArtifactRead {
            path: path.clone(),
            message: error.to_string(),
        })?;
        let (digest, length) =
            callisto_model::ArtifactDigest::from_reader(file).map_err(|error| GraphError::ArtifactRead {
                path: path.clone(),
                message: error.to_string(),
            })?;
        if digest != entry.digest || length != entry.byte_length {
            return Err(GraphError::ArtifactBytesMismatch { path });
        }

        verify_github_attestation(&path, entry, runner)?;
    }
    Ok(VerifiedArtifactManifest { manifest, root })
}

fn canonical_artifact_root(artifact_root: &Path) -> Result<PathBuf, GraphError> {
    let metadata = fs::metadata(artifact_root).map_err(|error| GraphError::ArtifactRead {
        path: artifact_root.to_path_buf(),
        message: error.to_string(),
    })?;
    if !metadata.is_dir() {
        return Err(GraphError::UnsafeArtifactPath {
            path: artifact_root.to_path_buf(),
            reason: "artifact root is not a directory",
        });
    }
    artifact_root.canonicalize().map_err(|error| GraphError::ArtifactRead {
        path: artifact_root.to_path_buf(),
        message: error.to_string(),
    })
}

