            package: package.id.display_name(),
        }));
    }
    let matrix = crate::commands::matrix(workspace, &crate::commands::MatrixOptions::default())?;
    Ok(matrix
        .platform_targets
        .keys()
        .next()
        .map(|package| CiReleaseRoute::PlatformPackage {
            package: package.clone(),
