167	/// NAIVE first pass: only handles (1) the manifest file entirely absent, and
168	/// (2) a well-formed workspace table with members/exclude arrays of
169	/// strings. Every other shape (workspace table absent, TOML unparseable,
170	/// members/exclude present but not an array-of-strings, members key
171	/// absent) falls back to an absent-filter (admit-all) result -- see the
172	/// `cargo_membership_tests`/`python_membership_tests` modules for the
173	/// exact fallback matrix this is pinned against.
174	pub(crate) fn read_membership(root: &Path, spec: &MembershipSpec) -> Membership {
175	    let content = match std::fs::read_to_string(root.join(spec.manifest_file_name)) {
176	        Ok(c) => c,
177	        Err(_) => return Membership::absent(),
178	    };
179	    let doc = match content.parse::<toml_edit::DocumentMut>() {
180	        Ok(d) => d,
181	        Err(_) => return Membership::absent(),
182	    };
183	
184	    let mut cursor: Option<&toml_edit::Item> = doc.get(spec.table_path[0]);
185	    for key in &spec.table_path[1..] {
186	        cursor = cursor.and_then(|c| c.get(*key));
187	    }
188	
189	    let hybrid_root = doc.get(spec.owner_key).is_some() && cursor.is_some();
190	    let Some(workspace) = cursor else {
191	        return Membership {
192	            members: None,
193	            exclude: NegatableGlobSet::empty(),
194	            hybrid_root,
195	        };
196	    };
197	    let members = workspace
198	        .get("members")
199	        .and_then(parse_toml_string_array)
200	        .map(|v| build_globset(&v));
201	    let exclude = workspace
202	        .get("exclude")
203	        .and_then(parse_toml_string_array)
204	        .map(|v| build_globset(&v))
205	        .unwrap_or_else(NegatableGlobSet::empty);
206	    Membership {
207	        members,
208	        exclude,
209	        hybrid_root,
210	    }
211	}
