161	            let rendered = crate::changelog::render_section(&cl.input)?;
162	            crate::changelog::prepend(
163	                root,
164	                &cl.changelog_path,
165	                &cl.input.package.display_name(),
166	                &rendered,
167	                permit,
168	            )?;
169	            modified_paths.push(cl.changelog_path.clone());
170	        }
171	
172	        for cs_path in &plan.consumed_changesets {
173	            deferred_deletions.push(cs_path.clone());
174	        }
175	
176	        if let Some(ref pre_state) = plan.pre_state_update {
177	            // Written from `plan.pre_json_path`, not derived from `consumed_changesets` (always empty in pre mode).
178	            let rel_pre_path = plan.pre_json_path.clone();
179	            let pre_path = root.join(&rel_pre_path);
180	            let text = match &plan.pre_json_original_text {
181	                Some(existing) => callisto_model::format::write_pre_json_preserving(pre_state, existing),
182	                None => callisto_model::format::write_pre_json(pre_state),
183	            };
