185	                path: rel_pre_path.clone(),
186	                message: e.to_string(),
187	            })?;
188	            modified_paths.push(rel_pre_path);
189	        } else if let Some(rel_pre_path) = &plan.delete_pre_json {
190	            deferred_deletions.push(rel_pre_path.clone());
191	        }
192	    }
