206	    let lockfile_ecosystems: &[(&str, Ecosystem)] = &[
207	        ("Cargo.lock", Ecosystem::Cargo),
208	        ("package-lock.json", Ecosystem::Npm),
209	        ("pnpm-lock.yaml", Ecosystem::Npm),
210	        ("yarn.lock", Ecosystem::Npm),
211	        ("bun.lock", Ecosystem::Npm),
212	        ("bun.lockb", Ecosystem::Npm),
213	        ("uv.lock", Ecosystem::Pypi),
214	        ("poetry.lock", Ecosystem::Pypi),
215	        ("pdm.lock", Ecosystem::Pypi),
