237	            } else {
238	                deleted.push(path);
239	            }
240	        }
241	
242	        if !existing.is_empty() {
243	            run_git_on_paths(runner, root, &["add", "--"], &existing)?;
244	        }
245	
246	        if !deleted.is_empty() {
247	            run_git_on_paths(runner, root, &["rm", "--cached", "--ignore-unmatch", "--"], &deleted)?;
248	        }
249	
