277	enum WriteStep<'p> {
278	    /// One load/mutate/persist cycle over a manifest only the `Manifest` trait writes: the
279	    /// version bump (idempotency-guarded) first, then every dependency rewrite, one persist.
280	    Manifest {
281	        path: &'p PathBuf,
282	        group: &'p ManifestWriteGroup,
283	    },
284	    /// The same cycle for a Cargo workspace root only the `WorkspaceCargoResolver` writes. Its
285	    /// writes carry no idempotency precondition.
286	    WorkspaceRoot {
287	        root_manifest: &'p PathBuf,
288	        group: &'p ManifestWriteGroup,
289	    },
290	    /// Mixed-routing manifests (written through both routes) are never batched: each write is
291	    /// its own load/persist, strictly in plan order.
292	    MixedManifestVersion {
293	        path: &'p PathBuf,
294	        bump: &'p PlannedBump,
