53	/// Flushes `dir`'s entries so a rename survives power loss. A directory that cannot be opened (Windows, or a `-wx`
54	/// mode) or a filesystem that cannot sync one (`Unsupported`, `InvalidInput`, macOS `ENOTSUP`) is skipped: the file is
55	/// already in place and failing the command now would misreport a write that happened. Any other failure, an I/O error
56	/// above all, means the rename may not be durable and is reported.
57	fn sync_directory(dir: &Path) -> io::Result<()> {
58	    #[cfg(unix)]
59	    {
60	        let Ok(handle) = std::fs::File::open(dir) else {
61	            return Ok(());
62	        };
63	        match handle.sync_all() {
64	            Err(error) if sync_unsupported(&error) => Ok(()),
65	            result => result,
66	        }
67	    }
68	    #[cfg(not(unix))]
69	    {
70	        let _ = dir;
71	        Ok(())
72	    }
73	}
