80	/// Returns the I/O error creating the parent directories or a temp file beside `path`, or
81	/// `IsADirectory`-style `InvalidInput` when `path` is a directory.
82	pub fn probe_atomic_write(path: &Path, permit: &ApplyPermit) -> io::Result<()> {
83	    let _permit = permit;
84	    if path.is_dir() {
85	        return Err(io::Error::new(
86	            io::ErrorKind::InvalidInput,
87	            "destination is a directory",
88	        ));
89	    }
90	    let raw_parent = path.parent().unwrap_or_else(|| Path::new("."));
91	    let parent = if raw_parent.as_os_str().is_empty() {
92	        Path::new(".")
93	    } else {
94	        raw_parent
95	    };
96	    std::fs::create_dir_all(parent)?;
97	    NamedTempFile::new_in(parent)?;
