404	            let mut handle = open_canonical(path, ctx)?;
405	            if write_version_guarded(handle.as_mut(), path, &bump.from, &bump.to, permit)? {
406	                handle.persist(permit)?;
407	            }
408	            Ok((*path).clone())
409	        }
410	        WriteStep::MixedWorkspaceVersion { root_manifest, to } => {
411	            let mut ws_res = WorkspaceCargoResolver::load(&root.join(root_manifest))?;
412	            ws_res.write_version(to, permit)?;
413	            ws_res.persist(permit)?;
414	            Ok((*root_manifest).clone())
415	        }
416	        WriteStep::MixedManifestRewrite { path, rewrite } => {
417	            let mut handle = open_canonical(path, ctx)?;
418	            rewrite_dependency(handle.as_mut(), rewrite, permit)?;
419	            handle.persist(permit)?;
420	            Ok((*path).clone())
421	        }
422	        WriteStep::MixedWorkspaceRewrite { root_manifest, rewrite } => {
423	            let mut ws_res = WorkspaceCargoResolver::load(&root.join(root_manifest))?;
424	            ws_res.write_dependency(&rewrite.key.name, rewrite.to.clone(), permit)?;
425	            ws_res.persist(permit)?;
426	            Ok((*root_manifest).clone())
427	        }
428	        WriteStep::PlatformVersion(write) => {
429	            let mut handle = open_canonical(&write.manifest, ctx)?;
430	            if write_version_guarded(handle.as_mut(), &write.manifest, &write.from, &write.version, permit)? {
431	                handle.persist(permit)?;
432	            }
433	            Ok(write.manifest.clone())
434	        }
435	        WriteStep::OptionalDependencies(update) => {
436	            let mut handle = open_canonical(&update.manifest, ctx)?;
437	            handle.update_optional_dependencies(&update.updates, permit)?;
438	            handle.persist(permit)?;
439	            Ok(update.manifest.clone())
440	        }
441	    }
