613	/// Platform manifest version writes and owner `optionalDependencies` pin updates
614	/// for every owner with a target version in `targets`. Sources: each owner's
615	/// attached platform manifests, plus `[[fixed-group]]`
616	/// platform members.
617	pub(crate) fn platform_version_writes<R: CommandRunner, D: DependencyResolver>(
618	    ws: &Workspace<'_, R, D>,
619	    targets: &std::collections::BTreeMap<callisto_model::PackageId, callisto_model::Version>,
620	) -> Result<(Vec<PlatformWrite>, Vec<crate::plan::OptionalDepUpdate>), GraphError> {
621	    let open_ctx = OpenContext::for_workspace_root(&ws.root)?;
622	    let pkg_map: HashMap<_, _> = ws.graph.packages().map(|p| (&p.id, p)).collect();
623	
624	    let mut members: Vec<(&callisto_model::PackageId, &std::path::Path, &str)> = Vec::new();
625	    for pkg in ws.graph.packages() {
626	        members.extend(
627	            ws.identity
628	                .attached_platforms(pkg)
629	                .map(|(name, path)| (&pkg.id, path, name)),
630	        );
631	    }
632	    for group in ws.config.groups.fixed.values() {
633	        for member in group.members(GroupMemberKind::PlatformManifest) {
634	            if let GroupMember::PlatformManifest { owner, path, name, .. } = member {
635	                members.push((owner, path, name));
636	            }
637	        }
638	    }
639	
640	    let mut seen = HashSet::new();
641	    let mut platform_writes = Vec::new();
642	    let mut optional_dep_map: std::collections::BTreeMap<std::path::PathBuf, Vec<(String, callisto_model::Version)>> =
643	        std::collections::BTreeMap::new();
644	    for (owner, path, name) in members {
645	        let Some(to) = targets.get(owner) else {
646	            continue;
647	        };
648	        if !seen.insert(path) {
649	            continue;
650	        }
651	        let fmt = callisto_model::ManifestFormat::from_path(path)?;
652	        let decl = callisto_model::ManifestDecl::new(path, ManifestRole::Canonical, fmt)?;
653	        let handle = open(&decl, &open_ctx)?;
654	        let current = handle.current_version()?;
655	        platform_writes.push(PlatformWrite {
656	            manifest: path.to_path_buf(),
657	            version: to.clone(),
658	            from: current,
659	        });
660	
661	        // A dual-manifest owner declares its platforms in package.json, not Cargo.toml.
662	        for owner_decl in pkg_map.get(owner).into_iter().flat_map(|p| p.canonical_manifests()) {
663	            let owner_fmt = callisto_model::ManifestFormat::from_path(&owner_decl.path)?;
664	            let owner_manifest_decl =
665	                callisto_model::ManifestDecl::new(owner_decl.path.clone(), ManifestRole::Canonical, owner_fmt)?;
666	            // Cached: owner manifest is shared across every platform target under it.
667	            let owner_handle = crate::manifest_cache::open_cached(&ws.manifest_cache, &owner_manifest_decl, &open_ctx)?;
668	            if owner_handle
669	                .iter_dependencies()
670	                .any(|dep| dep.kind == callisto_model::DepKind::Optional && dep.name == name)
671	            {
672	                optional_dep_map
673	                    .entry(owner_decl.path.clone())
674	                    .or_default()
675	                    .push((name.to_string(), to.clone()));
676	                break;
677	            }
678	        }
679	    }
680	    let optional_dep_updates = optional_dep_map
681	        .into_iter()
682	        .map(|(manifest, updates)| crate::plan::OptionalDepUpdate { manifest, updates })
683	        .collect();
684	    Ok((platform_writes, optional_dep_updates))
685	}
