/// Whether any of `paths` falls under one of `specs` as a literal `git`
/// pathspec would match it; `.` matches every path.
fn touches(paths: &[PathBuf], specs: &[PathBuf]) -> bool {
    paths.iter().any(|path| {
        specs
            .iter()
            .any(|spec| spec.as_path() == Path::new(".") || path.starts_with(spec))
    })
