98	fn problem(root: &Path, relative: &Path, target: Target, permit: &ApplyPermit) -> Option<String> {
99	    if relative.is_absolute()
100	        || relative
101	            .components()
102	            .any(|c| matches!(c, Component::ParentDir | Component::Prefix(_)))
103	    {
104	        return Some("is outside the workspace".to_string());
105	    }
106	    // Git cannot stage a path through a link, and replacing a link with a file would change what the repo records.
107	    let mut current = root.to_path_buf();
108	    for component in relative.components() {
109	        current.push(component);
110	        match std::fs::symlink_metadata(&current) {
111	            Ok(metadata) if metadata.file_type().is_symlink() => {
112	                return Some("is, or sits beneath, a symbolic link, which Git cannot stage".to_string());
113	            }
114	            Ok(_) => {}
115	            Err(error) if error.kind() == std::io::ErrorKind::NotFound => break,
116	            Err(error) => return Some(format!("cannot be inspected: {error}")),
117	        }
118	    }
119	    if target == Target::Removed {
120	        return None;
121	    }
122	
123	    let path = root.join(relative);
124	    match std::fs::metadata(&path) {
125	        Ok(metadata) if !metadata.is_file() => return Some("is not a regular file".to_string()),
126	        Ok(_) => {
127	            if let Err(error) = std::fs::File::open(&path) {
128	                return Some(format!("cannot be read: {error}"));
129	            }
130	        }
131	        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
132	            if target == Target::Existing {
133	                return Some("does not exist".to_string());
134	            }
135	        }
136	        Err(error) => return Some(format!("cannot be inspected: {error}")),
137	    }
138	    callisto_model::atomic::probe_atomic_write(&path, permit)
139	        .err()
140	        .map(|error| format!("cannot be written: {error}"))
141	}
