1	//! Callisto's single disk-write primitive.
2	//!
3	//! This lives in Layer 1 (`callisto-model`) rather than alongside the manifest
4	//! editors because durable file replacement is not a manifest concern: the
5	//! changelog writer, the pre-mode state file, and the config scaffolder all
6	//! need it too. Hosting it here means those callers do not have to take a
7	//! dependency on `callisto-manifests` purely to reach the filesystem.
8	
9	use std::io::{self, Write};
10	use std::path::Path;
11	
12	use crate::ApplyPermit;
13	use tempfile::NamedTempFile;
14	
15	/// Durably replaces `path`'s contents with `content`.
16	///
17	/// The [`ApplyPermit`] is unused at runtime and exists purely as a compile-time
18	/// obligation: this is callisto's single disk-write primitive, so requiring a
19	/// permit here means no code path can reach the filesystem without having first
20	/// consulted the dry-run flag. See [`crate::permit`].
21	///
22	/// # Errors
23	///
24	/// Returns the first I/O error encountered: creating parent directories, writing the temp file,
25	/// flushing, fsyncing, persisting (renaming) to `path`, or syncing the directory that holds it.
26	pub fn atomic_write(path: &Path, content: &str, permit: &ApplyPermit) -> io::Result<()> {
27	    let _permit = permit;
28	    let raw_parent = path.parent().unwrap_or_else(|| Path::new("."));
29	    let parent = if raw_parent.as_os_str().is_empty() {
30	        Path::new(".")
31	    } else {
32	        raw_parent
33	    };
34	    let created_parent = !parent.try_exists()?;
35	    std::fs::create_dir_all(parent)?;
36	
37	    let mut temp = temp_file_in(parent)?;
38	    match_existing_mode(temp.as_file(), path)?;
39	    temp.write_all(content.as_bytes())?;
40	    temp.flush()?;
41	    temp.as_file().sync_all()?;
42	    temp.persist(path).map_err(|e| e.error)?;
43	
44	    sync_directory(parent)?;
45	    // A directory this call created is itself a new entry in its parent.
46	    if created_parent {
47	        if let Some(grandparent) = parent.parent().filter(|dir| !dir.as_os_str().is_empty()) {
48	            sync_directory(grandparent)?;
49	        }
50	    }
51	    Ok(())
52	}
53	
54	/// A temp file whose mode follows the process umask like any new file, instead of `tempfile`'s owner-only `0600`.
55	fn temp_file_in(dir: &Path) -> io::Result<NamedTempFile> {
56	    #[cfg(unix)]
57	    {
58	        use std::os::unix::fs::PermissionsExt;
59	        tempfile::Builder::new()
60	            .permissions(std::fs::Permissions::from_mode(0o666))
61	            .tempfile_in(dir)
62	    }
63	    #[cfg(not(unix))]
64	    {
65	        NamedTempFile::new_in(dir)
66	    }
67	}
68	
69	/// Gives the temp file the mode of the file it replaces; a new file keeps the umask-derived mode.
70	fn match_existing_mode(temp: &std::fs::File, target: &Path) -> io::Result<()> {
71	    #[cfg(unix)]
72	    {
73	        use std::os::unix::fs::PermissionsExt;
74	        match std::fs::metadata(target) {
75	            Ok(existing) => {
76	                temp.set_permissions(std::fs::Permissions::from_mode(existing.permissions().mode() & 0o7777))
77	            }
78	            Err(error) if error.kind() == io::ErrorKind::NotFound => Ok(()),
79	            Err(error) => Err(error),
80	        }
81	    }
82	    #[cfg(not(unix))]
83	    {
84	        let _ = (temp, target);
85	        Ok(())
86	    }
87	}
88	
89	/// Flushes `dir`'s entries so a rename survives power loss. A directory that cannot be opened (Windows, or a `-wx`
90	/// mode) or a filesystem that cannot sync one (`Unsupported`, `InvalidInput`, macOS `ENOTSUP`) is skipped: the file is
91	/// already in place and failing the command now would misreport a write that happened. Any other failure, an I/O error
92	/// above all, means the rename may not be durable and is reported.
93	fn sync_directory(dir: &Path) -> io::Result<()> {
94	    #[cfg(unix)]
95	    {
96	        let Ok(handle) = std::fs::File::open(dir) else {
97	            return Ok(());
98	        };
99	        match handle.sync_all() {
100	            Err(error) if sync_unsupported(&error) => Ok(()),
101	            result => result,
102	        }
103	    }
104	    #[cfg(not(unix))]
105	    {
106	        let _ = dir;
107	        Ok(())
108	    }
109	}
