111	/// Fails now if [`atomic_write`] to `path` could not succeed, leaving no file behind.
112	/// A pre-existing regular file at `path` is accepted because the write replaces it.
113	///
114	/// # Errors
115	///
116	/// Returns the I/O error creating the parent directories or a temp file beside `path`, or
117	/// `IsADirectory`-style `InvalidInput` when `path` is a directory.
118	pub fn probe_atomic_write(path: &Path, permit: &ApplyPermit) -> io::Result<()> {
119	    let _permit = permit;
120	    if path.is_dir() {
121	        return Err(io::Error::new(
122	            io::ErrorKind::InvalidInput,
123	            "destination is a directory",
124	        ));
125	    }
126	    let raw_parent = path.parent().unwrap_or_else(|| Path::new("."));
127	    let parent = if raw_parent.as_os_str().is_empty() {
128	        Path::new(".")
129	    } else {
130	        raw_parent
131	    };
132	    std::fs::create_dir_all(parent)?;
133	    NamedTempFile::new_in(parent)?;
134	    sync_directory(parent)
135	}
