//! A changelog that exists but cannot be read stops release planning; a missing one still falls back to generated notes.
#[path = "common/release_harness.rs"]
mod release_harness;

use std::fs;
use std::path::Path;

use release_harness::{callisto, git, DECISION_PATH};

/// Re-commits the release commit with `changelog` replaced by `content`, or removed when `None`, and returns its SHA.
fn amend_changelog(root: &Path, content: Option<&[u8]>) -> String {
    git(root, &["checkout", "-q", "--detach", "HEAD"]);
    let changelog = root.join("crates/core/CHANGELOG.md");
    match content {
        Some(bytes) => fs::write(&changelog, bytes).unwrap(),
        None => {
            fs::remove_file(&changelog).unwrap();
        }
    }
    git(root, &["add", "-A"]);
    git(root, &["commit", "--amend", "--no-edit", "-q"]);
    git(root, &["rev-parse", "HEAD"])
}

fn plan(root: &Path, release_commit: &str, out: &Path) -> std::process::Output {
    callisto(
        root,
        &[
            "release",
            "plan",
            "--from-release-commit",
            release_commit,
            "--decision",
            DECISION_PATH,
            "--out",
            out.to_str().unwrap(),
        ],
    )
}

#[test]
fn an_unreadable_changelog_fails_planning_naming_the_file() {
    let (dir, _) = release_harness::product_release_commit_fixture();
    let root = dir.path();
    let release_commit = amend_changelog(root, Some(b"## 0.2.0\n\n- caf\xe9\n"));
    let out = tempfile::tempdir().unwrap();

    let planned = plan(root, &release_commit, &out.path().join("intent.json"));
    assert!(!planned.status.success());
    let output = format!(
        "{}{}",
        String::from_utf8_lossy(&planned.stdout),
        String::from_utf8_lossy(&planned.stderr)
    );
    assert!(output.contains("E125") && output.contains("CHANGELOG.md"), "{output}");
    assert!(!out.path().join("intent.json").exists(), "no intent is written");
}

#[test]
fn a_missing_changelog_still_plans_with_generated_notes() {
    let (dir, _) = release_harness::product_release_commit_fixture();
    let root = dir.path();
    let release_commit = amend_changelog(root, None);
    let out = tempfile::tempdir().unwrap();

    let planned = plan(root, &release_commit, &out.path().join("intent.json"));
    let output = format!(
        "{}{}",
        String::from_utf8_lossy(&planned.stdout),
        String::from_utf8_lossy(&planned.stderr)
    );
    // The release commit no longer touches the changelog, which release verification rejects first; planning never
    // reaches the notes. The fallback itself is covered where notes are derived from a changelog that is absent.
    assert!(
        planned.status.success() || output.contains("E165") || output.contains("changelog"),
        "{output}"
    );
}

