153	impl TagIndex {
154	    pub fn build<D: DependencyResolver>(
155	        git: &GitAccess<'_>,
156	        graph: &D,
157	        identity: &IdentityIndex,
158	        cfg: &ResolvedConfig,
159	    ) -> Result<Self, GraphError> {
160	        reject_shared_default_templates(graph)?;
161	        let mut last = BTreeMap::new();
162	        let mut templates = BTreeMap::new();
163	        let mut pre_cursor = BTreeMap::new();
164	        let mut diagnostics = Vec::new();
165	
166	        // Fetch the raw tag list exactly once for the whole build, not once
167	        // per package -- see `fetch_all_tags` for why.
168	        let all_tags = fetch_all_tags(git)?;
169	        let all_tags_set: std::collections::BTreeSet<String> = all_tags.iter().cloned().collect();
170	        let mut glob_cache: std::collections::HashMap<String, Vec<&str>> = std::collections::HashMap::new();
171	
172	        let mut rosters = crate::history::Rosters::default();
173	
174	        for pkg in graph.packages() {
175	            // `TagTemplate::default_for` is the single source of truth for a
176	            // package's default tag template -- matches `release.rs`'s own
177	            // `unwrap_or_else(|| callisto_model::TagTemplate::default_for(&package.id))`.
178	            // Deliberately not `TagTemplate::parse(&format!("{name}@{{version}}"))`:
179	            // `parse` additionally validates git-ref-name legality, which
180	            // `default_for` does not, so the two could previously reject/accept a
181	            // package name differently. Using `default_for` here removes that
182	            // extra validation from this call site to align with the
183	            // already-shipped `release.rs` behavior.
184	            let tmpl = pkg
185	                .tag_template
186	                .clone()
187	                .unwrap_or_else(|| TagTemplate::default_for(&pkg.id));
188	            let grammar = pkg.version_grammar()?;
189	            let mut chosen = take_chosen(
190	                select_from_tags_cached(&all_tags, &tmpl, grammar, &mut glob_cache)?,
191	                &mut diagnostics,
192	            );
193	            if chosen.is_none() {
194	                let package_ecosystems: Vec<Ecosystem> = pkg.canonical_manifests().map(|m| m.ecosystem()).collect();
195	                if let Some(previous) =
196	                    crate::config::resolve::resolve_package_config(&pkg.id, &package_ecosystems, cfg)?
197	                        .map(|package_config| package_config.previous_tag_templates.as_slice())
198	                {
199	                    for template in previous {
200	                        chosen = take_chosen(
201	                            select_from_tags_cached(&all_tags, template, grammar, &mut glob_cache)?,
202	                            &mut diagnostics,
203	                        );
204	                        if chosen.is_some() {
205	                            break;
206	                        }
207	                    }
208	                }
209	            }
210	            if chosen.is_none() && pkg.tag_template.is_none() && pkg.id.ecosystem().is_some() {
211	                // A promoted package keeps the `{name}@` tags it made while its name was unique.
212	                let unqualified = TagTemplate::default_for(&PackageId::Bare(pkg.id.name().to_string()));
213	                let same: Vec<&callisto_model::Package> = graph
214	                    .packages()
215	                    .filter(|p| p.id.ecosystem().is_some() && p.id.name() == pkg.id.name())
216	                    .collect();
217	                let mut owned = Vec::new();
218	                for tag in matching_tags(&all_tags, &unqualified)? {
219	                    if crate::history::sole_owner_at(git, tag, pkg.id.name(), &same, identity, &mut rosters)?
220	                        .is_some_and(|owner| owner.id == pkg.id)
221	                    {
222	                        owned.push(tag);
223	                    }
224	                }
225	                chosen = take_chosen(
226	                    select_last_tag(&unqualified, grammar, owned).map_err(GraphError::from)?,
227	                    &mut diagnostics,
228	                );
229	            }
230	            if pkg.tag_template.is_none() && pkg.id.ecosystem().is_none() {
231	                // A demoted package keeps the qualified tags it made while its name was shared.
232	                if let Some(manifest) = pkg.canonical_manifests().next() {
233	                    let qualified = TagTemplate::default_for(&PackageId::Prefixed {
234	                        ecosystem: manifest.ecosystem(),
235	                        name: pkg.id.name().to_string(),
236	                    });
237	                    let qualified_last = take_chosen(
238	                        select_last_tag(&qualified, grammar, all_tags.iter().map(String::as_str))
239	                            .map_err(GraphError::from)?,
240	                        &mut diagnostics,
241	                    );
242	                    chosen = newest(chosen, qualified_last);
243	                }
244	            }
245	            last.insert(pkg.id.clone(), chosen);
246	            templates.insert(pkg.id.clone(), tmpl);
247	            pre_cursor.insert(pkg.id.clone(), None);
248	        }
249	
250	        Ok(TagIndex {
251	            last,
252	            templates,
253	            pre_cursor,
254	            all_tags: all_tags_set,
255	            diagnostics,
256	        })
257	    }
