impl GroupTable {
    pub(crate) fn validate_syntactic(raw: &RawGroupTable) -> Result<(), ConfigError> {
        let members = |groups: &'_ [RawGroup]| -> Vec<(GroupName, Vec<String>)> {
            groups.iter().map(|g| (g.name.clone(), g.members.clone())).collect()
        };
        Self::validate_membership(&members(&raw.fixed), &members(&raw.linked))
    }

    /// The one membership check shared by the config path (raw member names) and
    /// [`GroupTable::try_from_groups`] (resolved package ids rendered as text).
    fn validate_membership(
        fixed: &[(GroupName, Vec<String>)],
        linked: &[(GroupName, Vec<String>)],
    ) -> Result<(), ConfigError> {
        let mut seen_names = BTreeSet::new();
        for group_list in [fixed, linked] {
            for (name, members) in group_list {
                if !seen_names.insert(name) {
                    return Err(ConfigError::DuplicateGroupName { group: name.clone() });
                }
                if members.is_empty() {
                    return Err(ConfigError::EmptyGroup { group: name.clone() });
                }
            }
        }

        // One map, populated fixed-then-linked (declaration order, not file
        // order): a fixed group's members are checked only against other
        // fixed groups seen so far (linked hasn't been touched yet at that
        // point), while a linked group's members are checked against BOTH
        // linked-so-far AND the now-fully-populated fixed map -- exactly the
        // asymmetric cross-check the two-separate-maps version encoded, but
        // as a natural consequence of processing order instead of a second
        // explicit lookup.
        let mut claimed: BTreeMap<&str, &GroupName> = BTreeMap::new();
        for group_list in [fixed, linked] {
            for (name, members) in group_list {
                for m in members {
                    if let Some(other) = claimed.insert(m.as_str(), name) {
                        if other == name {
                            return Err(ConfigError::DuplicateMemberInGroup {
                                group: name.clone(),
                                member: m.clone(),
                            });
                        }
                        return Err(ConfigError::ConflictingGroupNames {
                            group: name.clone(),
                            other: other.clone(),
                            member: m.clone(),
                        });
                    }
                }
            }
        }

        Ok(())
    }

    pub(crate) fn resolve(raw: &RawGroupTable, index: &IdentityIndex) -> Result<GroupTable, GraphError> {
        let mut fixed = BTreeMap::new();
        let mut linked = BTreeMap::new();
        let mut fixed_of = BTreeMap::new();
        let mut linked_of = BTreeMap::new();
        let mut claimed_by: BTreeMap<PackageId, GroupName> = BTreeMap::new();

        // One resolution loop parameterized on `GroupKind`, writing into
        // whichever kind's own output maps -- `claimed_by` is shared across
        // both passes exactly as before, so a package claimed by a fixed
        // group still conflicts if a linked group (or a second fixed group)
        // also claims it.
        for (kind, raw_groups, groups, membership) in [
            (GroupKind::Fixed, &raw.fixed, &mut fixed, &mut fixed_of),
            (GroupKind::Linked, &raw.linked, &mut linked, &mut linked_of),
        ] {
            for rg in raw_groups {
                let mut members = Vec::new();
                for name in &rg.members {
                    // Platform manifests take priority: their own native name
                    // is also registered in `index.native` (pointing at their
                    // owner), so `index.resolve` would otherwise resolve them
                    // to `GroupMember::Package(owner)` and silently drop the
                    // platform-manifest membership version.rs's platform-write
                    // derivation depends on.
                    if let Some((owner, path, role)) = index.platform.get(name) {
                        members.push(GroupMember::PlatformManifest {
                            owner: owner.clone(),
                            role: role.clone(),
                            path: path.clone(),
                            name: name.clone(),
                        });
                        continue;
                    }
                    match index.resolve(name) {
                        Ok(id) => {
                            if let Some(other) = claimed_by.get(&id) {
                                // The same package under another spelling, such as its primary and secondary native names.
                                if other == &rg.name {
                                    return Err(GraphError::Config(ConfigError::DuplicateMemberInGroup {
                                        group: rg.name.clone(),
                                        member: name.clone(),
                                    }));
                                }
                                return Err(GraphError::ConflictingGroupMembership {
                                    package: id.clone(),
                                    groups: vec![other.clone(), rg.name.clone()],
                                });
                            } else {
                                claimed_by.insert(id.clone(), rg.name.clone());
                            }
                            members.push(GroupMember::Package(id.clone()));
                            membership.insert(id, rg.name.clone());
                        }
                        Err(GraphError::UnknownPackage { .. }) => {
                            return Err(GraphError::MissingGroupMember {
                                group: rg.name.clone(),
                                member: name.clone(),
                            });
                        }
                        // Ambiguous (E103) and the colon form (E316) are reportable as they are.
                        Err(err) => return Err(err),
                    }
                }
                members.sort();
                groups.insert(
                    rg.name.clone(),
                    GroupDef {
                        name: rg.name.clone(),
                        kind,
                        members,
                    },
                );
            }
        }

        Ok(GroupTable {
            fixed,
            linked,
            fixed_of,
            linked_of,
        })
    }

