import os

for d, _, fs in os.walk('crates'):
    for f in fs:
        if not f.endswith('.rs'):
            continue
        p = os.path.join(d, f)
        s = open(p).read()
        o = s
        for eco in ('cargo', 'npm', 'pypi'):
            s = s.replace('cargo/' + eco + '/', eco + '/')
        if s != o:
            open(p, 'w').write(s)
            print(p)

