def qualify(m):
    name, sev = m.group(1), m.group(2)
    if name.split('/')[0] in ('cargo', 'npm', 'pypi'):
        return m.group(0)
    if name.startswith('@'):
        eco = 'npm'
    elif name in ('core-py',):
        eco = 'pypi'
    else:
        eco = 'cargo'
    return '"%s/%s:%s"' % (eco, name, sev)


