    assert_eq!(
        effects.matches("cargo publish").count(),
        1,
        "the publish is adopted, not repeated:\n{effects}"
    );

    let again = rig.run(root, &["release"]);
    assert_eq!(String::from_utf8_lossy(&again.stdout), "Nothing to release.\n");
}

