121	pub(crate) fn run_observation(
122	    runner: &dyn CommandRunner,
123	    program: &str,
124	    args: &[&str],
125	    cwd: &Path,
126	    timeout: Duration,
127	    quiet: bool,
128	) -> Result<Result<CommandOutput, CommandUnavailable>, GraphError> {
129	    let result = if quiet {
130	        runner.run_quiet(program, args, cwd, timeout)
131	    } else {
132	        runner.run_with_timeout(program, args, cwd, timeout)
133	    };
134	    match result {
135	        Ok(output) => Ok(Ok(output)),
136	        Err(CommandError::TimedOut { .. } | CommandError::Io { .. }) => Ok(Err(CommandUnavailable)),
137	        Err(other) => Err(other.into()),
138	    }
139	}
