141	/// The one bounded retry in the release path. It wraps read-only observations
142	/// only: an effect (publish, push, release create, asset upload) is never
143	/// re-issued from here, because a transient error cannot prove the first
144	/// attempt did not take effect.
145	pub(crate) fn retry_observation<T>(
146	    sleeper: &dyn Sleeper,
147	    mut attempt: impl FnMut() -> Result<Attempt<T>, GraphError>,
148	) -> Result<T, GraphError> {
149	    let mut exhausted = None;
150	    for index in 0..OBSERVATION_MAX_ATTEMPTS {
151	        match attempt()? {
152	            Attempt::Settled(value) => return Ok(value),
153	            Attempt::Transient { value, retry_after } => {
154	                exhausted = Some(value);
155	                if index + 1 < OBSERVATION_MAX_ATTEMPTS {
156	                    sleeper.sleep(
157	                        retry_after
158	                            .unwrap_or_else(|| observation_backoff(index))
159	                            .min(OBSERVATION_BACKOFF_CAP),
160	                    );
161	                }
162	            }
163	        }
164	    }
165	    Ok(exhausted.expect("at least one attempt always runs"))
166	}
