114	/// The one registry observation used by preflight and post-publish
115	/// confirmation, so the two can never disagree.
116	fn registry_observation<A: RegistryEcosystem + ?Sized>(
117	    adapter: &A,
118	    context: &ProviderContext<'_>,
119	    operation: &RegistryPublishOperation,
120	) -> Result<ProviderObservationV1, GraphError> {
121	    if !adapter.can_observe_versions() {
122	        return Ok(ProviderObservationV1::Indeterminate {
123	            cause: ProviderIndeterminateCause::UnsupportedProvider,
124	        });
125	    }
126	    policy::retry_observation(context.sleeper(), || adapter.observe_once(context, operation))
127	}
128	
129	/// The same observation, but an absence is treated as index-propagation lag
130	/// rather than an answer: this only runs after a publish client reported the
131	/// version as newly published.
132	fn confirmed_registry_observation<A: RegistryEcosystem + ?Sized>(
133	    adapter: &A,
134	    context: &ProviderContext<'_>,
135	    operation: &RegistryPublishOperation,
136	) -> Result<ProviderObservationV1, GraphError> {
137	    policy::retry_observation(context.sleeper(), || {
138	        Ok(match adapter.observe_once(context, operation)? {
139	            Attempt::Settled(ProviderObservationV1::Absent) => Attempt::Transient {
140	                value: ProviderObservationV1::Absent,
141	                retry_after: None,
142	            },
143	            settled_or_transient => settled_or_transient,
144	        })
145	    })
146	}
