365	    /// Runs from the package's Cargo workspace directory, so the same `.cargo/config.toml`
366	    /// registry definitions and credentials the publish effect uses apply --
367	    /// private registries and their auth are cargo's business, not ours.
368	    fn observe_once(
369	        &self,
370	        context: &ProviderContext<'_>,
371	        operation: &RegistryPublishOperation,
372	    ) -> Result<Attempt<ProviderObservationV1>, GraphError> {
373	        let spec = format!("{}@{}", operation.package_name, operation.version.render());
374	        let registry = cargo_registry_name(&operation.registry.key);
375	        let args = cargo_info_args(&spec, registry);
376	        let cwd = registry_argv::cargo_workspace_dir(context.root(), &operation.package_dir)?;
377	        let output = match run_observation(
378	            context.runner(),
379	            programs::CARGO,
380	            &args,
381	            &cwd,
382	            timeouts::REGISTRY_QUERY,
383	            true,
384	        )? {
385	            Ok(output) => output,
386	            Err(_unavailable) => return Ok(transient(ProviderIndeterminateCause::CommandFailed, None)),
387	        };
388	        Ok(classify_cargo_info(&output, &spec, &operation.version))
389	    }
