391	    fn publish(
392	        &self,
393	        context: &ProviderContext<'_>,
394	        _id: &ReleaseOperationId,
395	        operation: &RegistryPublishOperation,
396	        _artifacts: Option<&VerifiedArtifactManifest<'_>>,
397	    ) -> Result<CommandOutput, GraphError> {
398	        let registry_key =
399	            (operation.registry.key.as_str() != RegistryKey::CRATES_IO).then(|| operation.registry.key.as_str());
400	        let argv = registry_argv::cargo_publish_argv(
401	            context.root(),
402	            &operation.package_dir,
403	            &operation.package_name,
404	            &operation.version,
405	            registry_key,
406	        )?;
407	        run_argv(context, &argv)
