66	fn warn_if_registry_version_adopted(operation: &ReleaseOperationId) {
67	    let package = match &operation.role {
68	        ReleaseOperationRole::RegistryPublish { .. } => &operation.package,
69	        ReleaseOperationRole::PlatformPublish { platform, .. } => platform.name(),
70	        _ => return,
71	    };
72	    eprintln!(
73	        "warning: {package} {} is already published; skipping",
74	        operation.version
75	    );
76	}
