9	/// Whether running a step more than once has the same effect as running it once.
10	///
11	/// Decides what happens after an ambiguous attempt (timeout, HTTP 502/504, interruption): an idempotent step is
12	/// retried and, on resume, re-run; a non-idempotent step ends [`michi_core::pipeline::StepStatus::OutcomeUnknown`]
13	/// and is never replayed automatically.
14	#[non_exhaustive]
15	#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
16	pub enum Replay {
17	    /// Repeating the step could repeat its side effect. The default: a step must opt in to replay.
18	    #[default]
19	    NotIdempotent,
20	    /// Repeating the step is harmless.
21	    Idempotent,
22	}
23	
24	/// What a step attempt gets from the executor.
25	#[derive(Debug, Clone)]
26	pub struct StepContext {
27	    run_id: RunId,
28	    step_id: StepId,
29	    attempt: u32,
30	    cancellation: CancellationToken,
31	    deadline: Option<tokio::time::Instant>,
32	}
33	
34	impl StepContext {
35	    /// A context for attempt 0 with a fresh token and no deadline, for exercising a [`Step`] on its own (in tests,
36	    /// say). The executor builds its own.
37	    #[must_use]
38	    pub fn new(run_id: RunId, step_id: StepId) -> Self {
39	        Self { run_id, step_id, attempt: 0, cancellation: CancellationToken::new(), deadline: None }
40	    }
41	
42	    pub(crate) fn for_attempt(
43	        run_id: RunId,
44	        step_id: StepId,
45	        attempt: u32,
46	        cancellation: CancellationToken,
47	        deadline: Option<tokio::time::Instant>,
48	    ) -> Self {
49	        Self { run_id, step_id, attempt, cancellation, deadline }
50	    }
51	
52	    /// The run this attempt belongs to.
53	    #[must_use]
54	    pub fn run_id(&self) -> &RunId {
55	        &self.run_id
56	    }
57	
58	    /// The step being run.
59	    #[must_use]
60	    pub fn step_id(&self) -> &StepId {
61	        &self.step_id
62	    }
63	
64	    /// 0-based attempt number within this run of the step. For logging and backoff only; never part of the
65	    /// idempotency key.
66	    #[must_use]
67	    pub fn attempt(&self) -> u32 {
68	        self.attempt
69	    }
70	
71	    /// This step's cancellation token, a child of the run's. Watch it to stop cooperatively; once it fires, the
72	    /// executor drops the attempt after the cancellation grace period.
73	    #[must_use]
74	    pub fn cancellation(&self) -> &CancellationToken {
75	        &self.cancellation
76	    }
77	
78	    /// When the step's total deadline (across all attempts) expires, if one is set.
79	    #[must_use]
80	    pub fn deadline(&self) -> Option<tokio::time::Instant> {
81	        self.deadline
82	    }
83	
84	    /// Time left until [`StepContext::deadline`], if one is set.
85	    #[must_use]
86	    pub fn remaining(&self) -> Option<Duration> {
87	        self.deadline.map(|d| d.saturating_duration_since(tokio::time::Instant::now()))
88	    }
89	
90	    /// `run_id:step_id`: the same on every attempt and on resume, unique across runs. Pass it to a downstream that
91	    /// deduplicates to make the step's effect apply once.
92	    #[must_use]
93	    pub fn idempotency_key(&self) -> michi_core::resilience::IdempotencyKey {
94	        let mut key = String::with_capacity(self.run_id.as_str().len() + 1 + self.step_id.as_str().len());
95	        key.push_str(self.run_id.as_str());
96	        key.push(':');
97	        key.push_str(self.step_id.as_str());
98	        michi_core::resilience::IdempotencyKey::new(key)
99	    }
100	}
101	
102	/// The boxed future a [`Step`] attempt returns.
103	pub type StepFuture<'a> = Pin<Box<dyn Future<Output = Result<(), ExecutionError>> + Send + 'a>>;
104	
105	/// What a plan step runs. Object-safe, so steps of different types share one plan without an async-trait
106	/// dependency.
107	///
108	/// # Replay safety
109	///
110	/// The executor may run a step more than once: on retry within a run, and on resume. Every failed attempt is
111	/// classified by whether it could have taken effect ([`crate::ReplayClass`]):
112	///
113	/// - **Not executed**: circuit open, or the step returned [`ExecutionError::Cancelled`]. Not retried; safe to run on
114	///   resume.
115	/// - **Rejected**: HTTP 429 or 503, or `Failed { retryable: true }`. Retried for every step.
116	/// - **Ambiguous**: a timeout, HTTP 502 or 504, or an interruption. Retried only if [`Step::replay`] is
117	///   [`Replay::Idempotent`]; otherwise the step ends `OutcomeUnknown`.
118	/// - **Definitive**: everything else. Not retried.
119	///
120	/// A step classifies its own outcome by the error it returns, so it must classify honestly: a step that may have
121	/// committed its effect must not report 429, 503, `Failed { retryable: true }` or `Cancelled`. It reports 502, 504,
122	/// a timeout or a non-retryable error instead.
123	pub trait Step: Send + Sync {
124	    /// Runs one attempt.
125	    fn run<'a>(&'a self, ctx: &'a StepContext) -> StepFuture<'a>;
126	
127	    /// Whether the step may be replayed after an ambiguous outcome. Defaults to [`Replay::NotIdempotent`].
128	    fn replay(&self) -> Replay {
129	        Replay::NotIdempotent
130	    }
131	}
132	
133	/// [`Step`] over an async closure, built by [`step_fn`].
134	pub struct FnStep<F> {
135	    f: F,
136	    replay: Replay,
137	}
138	
139	impl<F> FnStep<F> {
140	    /// Declares the step idempotent ([`Replay::Idempotent`]).
141	    #[must_use]
142	    pub fn idempotent(mut self) -> Self {
143	        self.replay = Replay::Idempotent;
144	        self
145	    }
146	}
147	
148	/// Adapts an async closure into a [`Step`]. The closure receives an owned clone of the attempt's [`StepContext`].
149	/// The step is [`Replay::NotIdempotent`] unless [`FnStep::idempotent`] is called.
150	pub fn step_fn<F, Fut>(f: F) -> FnStep<F>
151	where
152	    F: Fn(StepContext) -> Fut + Send + Sync,
153	    Fut: Future<Output = Result<(), ExecutionError>> + Send + 'static,
154	{
155	    FnStep { f, replay: Replay::NotIdempotent }
156	}
157	
158	impl<F, Fut> Step for FnStep<F>
159	where
160	    F: Fn(StepContext) -> Fut + Send + Sync,
161	    Fut: Future<Output = Result<(), ExecutionError>> + Send + 'static,
162	{
163	    fn run<'a>(&'a self, ctx: &'a StepContext) -> StepFuture<'a> {
164	        Box::pin((self.f)(ctx.clone()))
165	    }
166	
167	    fn replay(&self) -> Replay {
168	        self.replay
169	    }
170	}
171	
172	#[cfg(test)]
173	mod tests {
174	    use super::*;
175	
176	    fn ctx() -> StepContext {
177	        StepContext::new(RunId::try_new("run-7").unwrap(), StepId::try_new("upload").unwrap())
178	    }
179	
180	    #[test]
181	    fn idempotency_key_is_run_colon_step_and_ignores_the_attempt() {
182	        let first = ctx();
183	        let retry = StepContext::for_attempt(
184	            first.run_id().clone(),
185	            first.step_id().clone(),
186	            3,
187	            CancellationToken::new(),
188	            None,
189	        );
190	        assert_eq!(first.idempotency_key().as_str(), "run-7:upload");
191	        assert_eq!(retry.idempotency_key(), first.idempotency_key());
192	    }
193	
194	    #[tokio::test(start_paused = true)]
195	    async fn step_fn_adapts_a_closure_and_defaults_to_not_idempotent() {
196	        let step = step_fn(|ctx: StepContext| async move {
197	            assert_eq!(ctx.step_id().as_str(), "upload");
198	            Ok(())
199	        });
200	        assert_eq!(step.replay(), Replay::NotIdempotent);
201	        assert_eq!(step.run(&ctx()).await, Ok(()));
202	        assert_eq!(step_fn(|_| async { Ok(()) }).idempotent().replay(), Replay::Idempotent);
203	    }
204	
205	    #[test]
206	    fn step_is_object_safe() {
207	        let steps: Vec<Box<dyn Step>> = vec![Box::new(step_fn(|_| async { Ok(()) }))];
208	        assert_eq!(steps.len(), 1);
209	    }
210	}
