31	/// What a step failure does to the rest of the run.
32	#[non_exhaustive]
33	#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
34	pub enum FailurePolicy {
35	    /// Skip the failed step's transitive dependents; independent branches keep running.
36	    #[default]
37	    SkipDependents,
38	    /// Stop dispatching and cancel running steps (after the cancellation grace period, their attempts are dropped).
39	    FailFast,
40	}
