42	/// Called synchronously from the scheduler loop as steps start and finish, so callers can persist progress and
43	/// rebuild the run with [`RunRecord::from_parts`] after a crash. A closure `Fn(&RunId, &StepRecord)` implements it
44	/// (finish events only). Keep it quick: it runs between dispatches.
45	///
46	/// A panic in an observer method is caught: the run continues, later events are still delivered, and the panic is
47	/// counted in [`RunRecord::observer_panics`]. (The process's panic hook still runs, so the default hook prints it.)
48	pub trait StepObserver: Send + Sync {
49	    /// A step is about to be dispatched. Persist [`StepRecord::in_flight`] here to make a crash mid-step visible.
50	    fn on_step_started(&self, run_id: &RunId, step_id: &StepId) {
51	        let _ = (run_id, step_id);
52	    }
53	
54	    /// A step reached its terminal status in this run: ran, was skipped, or (on resume) was carried over.
55	    fn on_step_finished(&self, run_id: &RunId, record: &StepRecord);
56	}
57	
58	impl<F> StepObserver for F
59	where
60	    F: Fn(&RunId, &StepRecord) + Send + Sync,
61	{
62	    fn on_step_finished(&self, run_id: &RunId, record: &StepRecord) {
63	        self(run_id, record);
64	    }
65	}
