293	/// Continues the run in `prior` under its run id, so idempotency keys stay the same.
294	///
295	/// Refuses, before running anything, a plan whose fingerprint differs from the record's, a record naming a step the
296	/// plan lacks, and a verdict for a step that is not awaiting verification. Then: `Completed` and `CompletedEarlier`
297	/// steps become `CompletedEarlier` and are not run; `Failed`, `Skipped`, `NotRun`, `Pending` and missing steps run
298	/// again; `OutcomeUnknown`, `Panicked` and `Running` steps run again only if the step is [`crate::Replay::Idempotent`]
299	/// or the caller verified them as [`Verification::NotApplied`], become `CompletedEarlier` if verified as
300	/// [`Verification::Applied`], and otherwise keep their prior record (a `Running` one becomes
301	/// `OutcomeUnknown(Interrupted)`).
302	///
303	/// At least once per step: a step can run again if the process stopped after its effect but before its record was
304	/// saved. Not incremental recomputation: a completed step is not re-run because its inputs changed.
305	pub async fn resume(prior: &RunRecord, plan: &Plan, opts: &ResumeOptions) -> Result<RunRecord, ResumeError> {
306	    if prior.plan_fingerprint() != plan.fingerprint() {
307	        return Err(ResumeError::FingerprintMismatch { record: prior.plan_fingerprint(), plan: plan.fingerprint() });
308	    }
309	    if let Some(unknown) = prior.steps().iter().find(|s| plan.index_of(s.step_id()).is_none()) {
310	        return Err(ResumeError::UnknownStep { step_id: unknown.step_id().clone() });
311	    }
312	    for step_id in opts.verified.keys() {
313	        let status = prior.step(step_id).map(StepRecord::status);
314	        if !matches!(status, Some(StepStatus::OutcomeUnknown(_) | StepStatus::Panicked | StepStatus::Running)) {
315	            return Err(ResumeError::NotAwaitingVerification {
316	                step_id: step_id.clone(),
317	                status: status.map_or("missing", |s| s.label()),
318	            });
319	        }
320	    }
321	    let initial = plan
322	        .steps()
323	        .iter()
324	        .map(|step| {
325	            let Some(prev) = prior.step(step.id()) else { return Initial::Run };
326	            match prev.status() {
327	                StepStatus::Completed | StepStatus::CompletedEarlier => {
328	                    Initial::Done(Box::new(carried_over(prev, "completed earlier in this run")))
329	                }
330	                StepStatus::OutcomeUnknown(_) | StepStatus::Panicked | StepStatus::Running => {
331	                    match opts.verified.get(step.id()) {
332	                        Some(Verification::Applied) => {
333	                            Initial::Done(Box::new(carried_over(prev, "verified as applied by the caller")))
334	                        }
335	                        Some(Verification::NotApplied) => Initial::Run,
336	                        None if step.runner().replay() == crate::Replay::Idempotent => Initial::Run,
337	                        None => Initial::Done(Box::new(kept_unresolved(prev))),
338	                    }
339	                }
340	                _ => Initial::Run,
341	            }
342	        })
343	        .collect();
344	    Ok(scheduler::run(plan, prior.run_id().clone(), &opts.exec, initial).await)
345	}
