348	fn carried_over(prev: &StepRecord, reason: &str) -> StepRecord {
349	    let mut record = StepRecord::new(prev.step_id().clone(), prev.name().to_string(), StepStatus::CompletedEarlier);
350	    record.reason = Some(reason.to_string());
351	    record.attempts = prev.attempts().to_vec();
