355	/// A prior outcome still in doubt, kept as it was (timing cleared). A step left `Running` by a crash becomes
356	/// `OutcomeUnknown(Interrupted)`.
357	fn kept_unresolved(prev: &StepRecord) -> StepRecord {
358	    let mut record = prev.clone();
359	    record.started_at = None;
360	    record.elapsed = None;
361	    if record.status == StepStatus::Running {
362	        record.status = StepStatus::OutcomeUnknown(UnknownCause::Interrupted);
363	        record.error =
364	            Some(ExecutionError::AmbiguousOutcome { source: Box::new(ExecutionError::Interrupted { elapsed_ms: 0 }) });
365	        record.reason =
366	            Some("in flight when the previous process stopped; verify whether it took effect, then resume".to_string());
367	    }
368	    record
369	}
