6	/// Steps of a cycle path printed before the rest is summarized.
7	const PATH_LIMIT: usize = 8;
8	
9	/// One strongly connected component that forms a cycle.
10	#[non_exhaustive]
11	#[derive(Debug, Clone, PartialEq, Eq)]
12	pub struct Cycle<K> {
13	    members: Vec<K>,
14	    path: Vec<K>,
15	}
16	
17	impl<K> Cycle<K> {
18	    pub(crate) fn new(members: Vec<K>, path: Vec<K>) -> Self {
19	        Self { members, path }
20	    }
21	
22	    /// Every node of the component, in the validation's [`crate::Order`].
23	    #[must_use]
24	    pub fn members(&self) -> &[K] {
25	        &self.members
26	    }
27	
28	    /// One shortest loop through the first member: each node depends on the next, and the last depends on the first.
29	    #[must_use]
30	    pub fn path(&self) -> &[K] {
31	        &self.path
32	    }
33	
34	    fn write(
35	        &self,
36	        f: &mut fmt::Formatter<'_>,
37	        key: &dyn Fn(&K, &mut fmt::Formatter<'_>) -> fmt::Result,
38	    ) -> fmt::Result {
39	        let Some(first) = self.path.first() else { return f.write_str("dependency cycle") };
40	        f.write_str("dependency cycle: ")?;
41	        key(first, f)?;
42	        for (i, k) in self.path.iter().skip(1).enumerate() {
43	            if i == PATH_LIMIT {
44	                return write!(f, " … and {} more", self.path.len() - 1 - PATH_LIMIT);
45	            }
46	            f.write_str(if i == 0 { " depends on " } else { ", which depends on " })?;
47	            key(k, f)?;
48	        }
49	        f.write_str(if self.path.len() == 1 { " depends on " } else { ", which depends on " })?;
50	        key(first, f)
51	    }
52	}
53	
54	/// One problem found by validation.
55	#[non_exhaustive]
56	#[derive(Debug, Clone, PartialEq, Eq)]
57	pub enum Violation<K> {
58	    /// A later declaration reuses an earlier node's key. Its edges were dropped.
59	    DuplicateNode {
60	        /// The repeated key.
61	        key: K,
62	    },
63	    /// A node depends on a key no node has.
64	    UnknownDependency {
65	        /// The node declaring the dependency.
66	        dependent: K,
67	        /// The missing key.
68	        prerequisite: K,
69	    },
70	    /// A node depends on itself. Reported once per node, never as a cycle.
71	    SelfDependency {
72	        /// The node.
73	        key: K,
74	    },
75	    /// Nodes that depend on each other in a loop.
76	    Cycle(Cycle<K>),
77	    /// More than `u32::MAX - 1` nodes were declared; the rest were dropped.
78	    TooManyNodes,
79	}
80	
81	impl<K> Violation<K> {
82	    fn write(
83	        &self,
84	        f: &mut fmt::Formatter<'_>,
85	        key: &dyn Fn(&K, &mut fmt::Formatter<'_>) -> fmt::Result,
86	    ) -> fmt::Result {
87	        match self {
88	            Self::DuplicateNode { key: k } => {
89	                f.write_str("duplicate node ")?;
90	                key(k, f)
91	            }
92	            Self::UnknownDependency { dependent, prerequisite } => {
93	                key(dependent, f)?;
94	                f.write_str(" depends on unknown node ")?;
95	                key(prerequisite, f)
96	            }
97	            Self::SelfDependency { key: k } => {
98	                key(k, f)?;
99	                f.write_str(" depends on itself")
100	            }
101	            Self::Cycle(cycle) => cycle.write(f, key),
102	            Self::TooManyNodes => write!(f, "more than {} nodes", u32::MAX - 1),
103	        }
104	    }
105	}
106	
107	impl<K: fmt::Display> fmt::Display for Violation<K> {
108	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
109	        self.write(f, &|k, f| k.fmt(f))
110	    }
111	}
112	
113	impl<K: fmt::Display> fmt::Display for Cycle<K> {
114	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
115	        self.write(f, &|k, f| k.fmt(f))
116	    }
117	}
118	
119	/// Every problem validation found, in a fixed order: duplicates, then edge problems by the dependent's declaration
120	/// position and the edge's, then cycles in the validation's [`crate::Order`]. Never empty.
121	#[derive(Debug, Clone, PartialEq, Eq)]
122	pub struct Violations<K> {
123	    list: Vec<Violation<K>>,
124	}
125	
126	impl<K> Violations<K> {
127	    pub(crate) fn new(list: Vec<Violation<K>>) -> Self {
128	        Self { list }
129	    }
130	
131	    /// The violations.
132	    #[must_use]
133	    pub fn as_slice(&self) -> &[Violation<K>] {
134	        &self.list
135	    }
136	
137	    /// The violations, owned.
138	    #[must_use]
139	    pub fn into_vec(self) -> Vec<Violation<K>> {
140	        self.list
141	    }
142	
143	    /// Iterates the violations.
144	    pub fn iter(&self) -> core::slice::Iter<'_, Violation<K>> {
145	        self.list.iter()
146	    }
147	
148	    /// Renders with `key` writing each key, for key types without `Display`.
149	    pub fn display_with<F>(&self, key: F) -> impl fmt::Display + '_
150	    where
151	        F: Fn(&K, &mut fmt::Formatter<'_>) -> fmt::Result + 'static,
152	    {
153	        DisplayWith { violations: self, key }
154	    }
155	
156	    fn write(
157	        &self,
158	        f: &mut fmt::Formatter<'_>,
159	        key: &dyn Fn(&K, &mut fmt::Formatter<'_>) -> fmt::Result,
160	    ) -> fmt::Result {
161	        for (i, v) in self.list.iter().enumerate() {
162	            if i > 0 {
163	                f.write_str("; ")?;
164	            }
165	            v.write(f, key)?;
166	        }
167	        Ok(())
168	    }
169	}
170	
171	impl<'a, K> IntoIterator for &'a Violations<K> {
172	    type Item = &'a Violation<K>;
173	    type IntoIter = core::slice::Iter<'a, Violation<K>>;
174	    fn into_iter(self) -> Self::IntoIter {
175	        self.list.iter()
176	    }
177	}
178	
179	impl<K> IntoIterator for Violations<K> {
180	    type Item = Violation<K>;
181	    type IntoIter = alloc::vec::IntoIter<Violation<K>>;
182	    fn into_iter(self) -> Self::IntoIter {
183	        self.list.into_iter()
184	    }
185	}
186	
187	impl<K: fmt::Display> fmt::Display for Violations<K> {
188	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
189	        self.write(f, &|k, f| k.fmt(f))
190	    }
191	}
192	
193	impl<K: fmt::Debug + fmt::Display> core::error::Error for Violations<K> {}
194	
195	struct DisplayWith<'a, K, F> {
196	    violations: &'a Violations<K>,
197	    key: F,
198	}
199	
200	impl<K, F> fmt::Display for DisplayWith<'_, K, F>
201	where
202	    F: Fn(&K, &mut fmt::Formatter<'_>) -> fmt::Result,
203	{
204	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
205	        self.violations.write(f, &self.key)
206	    }
207	}
