29	/// Same algorithm as [`toposort_impl`], but the caller decides per-edge
30	/// whether it counts as an ordering constraint, rather than a single
31	/// `DepKind` list applied uniformly to every pair. This is what lets
32	/// a caller exclude a `Dev` edge only between the
33	/// specific packages that form a cycle, instead of dropping `Dev` ordering
34	/// for every package in `subset` the moment any one Dev cycle exists.
35	pub fn toposort_with_edge_filter<F, P>(
36	    subset: &HashSet<PackageId>,
37	    all_packages: &[PackageId],
38	    outgoing_edges: F,
39	    edge_allowed: P,
40	) -> Result<Vec<PackageId>, GraphError>
41	where
42	    F: Fn(&PackageId) -> Vec<(PackageId, DepKind)>,
43	    P: Fn(&PackageId, &PackageId, DepKind) -> bool,
44	{
45	    let members: BTreeSet<PackageId> = subset.iter().cloned().collect();
46	    // Build a HashSet once so validation is O(N) rather than O(N²) slice scans.
47	    let all_set: std::collections::HashSet<&PackageId> = all_packages.iter().collect();
48	    for id in &members {
49	        if !all_set.contains(id) {
50	            return Err(GraphError::UnknownPackage { id: id.clone() });
51	        }
52	    }
53	
54	    let mut in_degree: BTreeMap<PackageId, usize> = BTreeMap::new();
55	    let mut adj: BTreeMap<PackageId, Vec<PackageId>> = BTreeMap::new();
56	
57	    for u in &members {
58	        in_degree.insert(u.clone(), 0);
59	        adj.insert(u.clone(), Vec::new());
60	    }
61	
62	    for u in &members {
63	        for (v, kind) in outgoing_edges(u) {
64	            if members.contains(&v) && edge_allowed(u, &v, kind) {
65	                adj.get_mut(&v)
66	                    .expect("every member has an adjacency list")
67	                    .push(u.clone());
68	                *in_degree.get_mut(u).expect("every member has an in-degree") += 1;
69	            }
70	        }
71	    }
72	
73	    let mut queue: BTreeSet<PackageId> = BTreeSet::new();
74	    for (u, &deg) in &in_degree {
75	        if deg == 0 {
76	            queue.insert(u.clone());
77	        }
78	    }
79	
80	    let mut sorted = Vec::new();
81	    while let Some(u) = queue.pop_first() {
82	        sorted.push(u.clone());
83	        if let Some(neighbors) = adj.get(&u) {
84	            for v in neighbors {
85	                let deg = in_degree.get_mut(v).expect("every member has an in-degree");
86	                *deg -= 1;
87	                if *deg == 0 {
88	                    queue.insert(v.clone());
89	                }
90	            }
91	        }
92	    }
93	
94	    if sorted.len() < members.len() {
95	        let set: HashSet<PackageId> = sorted.iter().cloned().collect();
96	        let remaining: Vec<PackageId> = members.into_iter().filter(|m| !set.contains(m)).collect();
97	        let cycle = extract_cycle(&remaining, &adj);
98	        return Err(GraphError::Cycle { cycle });
99	    }
100	
101	    Ok(sorted)
102	}
