104	/// Edge kinds cascade/version-bump propagation cares about: a `Dev`-only
105	/// dependency change correctly never forces a consumer's version to bump.
106	pub const CASCADE_ORDERING_KINDS: &[DepKind] = &[DepKind::Runtime, DepKind::Build, DepKind::Optional];
107	
108	/// Edge kinds publish ordering cares about: cascade's kinds, plus `Dev`.
109	/// `cargo publish` verifies by building the packaged tarball, which needs every
110	/// dependency -- `[dev-dependencies]` included -- resolvable from the registry.
111	pub const PUBLISH_ORDERING_KINDS: &[DepKind] = &[DepKind::Runtime, DepKind::Build, DepKind::Optional, DepKind::Dev];
112	
113	/// Which dependency edges order a publish: every [`PUBLISH_ORDERING_KINDS`] edge,
114	/// except a `Dev` edge between two packages of the same cycle.
115	///
116	/// Mutual dev-only dependencies (cross-integration tests) are legitimate, so a
117	/// `Dev` edge inside a cyclic component is dropped; a `Dev` edge anywhere else
118	/// still orders. A cycle that survives with every `Dev` edge excluded is a real
119	/// `Runtime`/`Build`/`Optional` cycle and fails construction with
120	/// [`GraphError::Cycle`]. Used by release derivation.
121	pub struct PublishEdgeFilter {
122	    dev_cycles: Vec<HashSet<PackageId>>,
123	}
124	
125	impl PublishEdgeFilter {
126	    pub fn new<F>(
127	        subset: &HashSet<PackageId>,
128	        all_packages: &[PackageId],
129	        outgoing_edges: F,
130	    ) -> Result<Self, GraphError>
131	    where
132	        F: Fn(&PackageId) -> Vec<(PackageId, DepKind)>,
133	    {
134	        toposort_impl(subset, all_packages, CASCADE_ORDERING_KINDS, &outgoing_edges)?;
135	        Ok(PublishEdgeFilter {
136	            dev_cycles: cyclic_sccs(subset, &outgoing_edges, PUBLISH_ORDERING_KINDS),
137	        })

