137	        })
138	    }
139	
140	    /// Whether the `from -> to` edge of `kind` is a publish-ordering constraint.
141	    pub fn allows(&self, from: &PackageId, to: &PackageId, kind: DepKind) -> bool {
142	        if !PUBLISH_ORDERING_KINDS.contains(&kind) {
143	            return false;
144	        }
145	        kind != DepKind::Dev
146	            || !self
147	                .dev_cycles
148	                .iter()
149	                .any(|component| component.contains(from) && component.contains(to))
