153	/// Returns every non-trivial strongly-connected component (size > 1, or a
154	/// single self-looping node) of `subset` under the edges `ordering_kinds`
155	/// selects — the full member set, not just what's left after a failed
156	/// toposort. Used by [`PublishEdgeFilter`] to scope a Dev-cycle
157	/// exclusion to exactly the packages that participate in a cycle, rather
158	/// than excluding Dev edges across the whole subset.
159	pub fn cyclic_sccs<F>(
160	    subset: &HashSet<PackageId>,
161	    outgoing_edges: F,
162	    ordering_kinds: &[DepKind],
163	) -> Vec<HashSet<PackageId>>
164	where
165	    F: Fn(&PackageId) -> Vec<(PackageId, DepKind)>,
166	{
167	    use petgraph::algo::tarjan_scc;
168	    use petgraph::graph::DiGraph;
169	
170	    let members: BTreeSet<PackageId> = subset.iter().cloned().collect();
171	    let mut graph = DiGraph::<PackageId, ()>::new();
172	    let mut node_map = BTreeMap::new();
173	
174	    for pkg in &members {
175	        let idx = graph.add_node(pkg.clone());
176	        node_map.insert(pkg.clone(), idx);
177	    }
178	
179	    for u in &members {
180	        for (v, kind) in outgoing_edges(u) {
181	            if members.contains(&v)
182	                && ordering_kinds.contains(&kind)
183	                && let (Some(&u_idx), Some(&v_idx)) = (node_map.get(u), node_map.get(&v))
184	            {
185	                graph.add_edge(u_idx, v_idx, ());
186	            }
187	        }
188	    }
189	
190	    tarjan_scc(&graph)
191	        .into_iter()
192	        .filter(|scc| scc.len() > 1 || (scc.len() == 1 && graph.contains_edge(scc[0], scc[0])))
193	        .map(|scc| scc.into_iter().map(|idx| graph[idx].clone()).collect())
194	        .collect()
195	}
