197	fn extract_cycle(remaining: &[PackageId], adj: &BTreeMap<PackageId, Vec<PackageId>>) -> Vec<PackageId> {
198	    use petgraph::algo::tarjan_scc;
199	    use petgraph::graph::DiGraph;
200	
201	    let mut graph = DiGraph::<PackageId, ()>::new();
202	    let mut node_map = BTreeMap::new();
203	    let mut rev_map = BTreeMap::new();
204	
205	    for pkg in remaining {
206	        let idx = graph.add_node(pkg.clone());
207	        node_map.insert(pkg.clone(), idx);
208	        rev_map.insert(idx, pkg.clone());
209	    }
210	
211	    for u in remaining {
212	        if let Some(neighbors) = adj.get(u) {
213	            for v in neighbors {
214	                if let (Some(&u_idx), Some(&v_idx)) = (node_map.get(u), node_map.get(v)) {
215	                    graph.add_edge(u_idx, v_idx, ());
216	                }
217	            }
218	        }
219	    }
220	
221	    let sccs = tarjan_scc(&graph);
222	    for scc in sccs {
223	        let is_self_loop = scc.len() == 1 && graph.contains_edge(scc[0], scc[0]);
224	        if scc.len() > 1 || is_self_loop {
225	            let mut cycle = Vec::new();
226	            let start_idx = scc[0];
227	            let mut curr = start_idx;
228	            let scc_set: std::collections::HashSet<_> = scc.iter().copied().collect();
229	
230	            cycle.push(rev_map[&curr].clone());
231	            loop {
232	                let mut next_found = None;
233	                for neighbor in graph.neighbors(curr) {
234	                    if scc_set.contains(&neighbor) {
235	                        next_found = Some(neighbor);
236	                        break;
237	                    }
238	                }
239	
240	                if let Some(next) = next_found {
241	                    curr = next;
242	                    cycle.push(rev_map[&curr].clone());
243	                    if curr == start_idx {
244	                        break;
245	                    }
246	                } else {
247	                    break;
248	                }
249	            }
250	
251	            if cycle.len() > 1 {
252	                return cycle;
253	            }
254	        }
255	    }
256	
257	    remaining.to_vec()
258	}
