        // Many revisions go through stdin so the argument list stays short.
        const MAX_REVS_AS_ARGUMENTS: usize = 2000;
        let output = if revs.len() <= MAX_REVS_AS_ARGUMENTS {
            args.extend(revs.iter().map(String::as_str));
