use std::time::Instant;

fn main() {
    let path = std::env::args().nth(1).expect("repo path");
    let repo = gix::open(&path).expect("open");

    // 1. every tag with the commit it ends at
    let started = Instant::now();
    let mut tags = Vec::new();
    for reference in repo.references().unwrap().tags().unwrap() {
        let mut reference = reference.unwrap();
        let name = reference.name().shorten().to_string();
        let id = reference.peel_to_id().unwrap().detach();
        tags.push((name, id));
    }
    println!("tags with commits : {:>6} ms  ({} tags)", started.elapsed().as_millis(), tags.len());

    // 2. the manifest at every tag
    let started = Instant::now();
    let mut bytes = 0usize;
    for (name, id) in &tags {
        let package = name.trim_end_matches("@1.0.0");
        let commit = repo.find_commit(*id).unwrap();
        let tree = commit.tree().unwrap();
        let entry = tree
            .lookup_entry_by_path(format!("crates/{package}/Cargo.toml"))
            .unwrap()
            .expect("manifest");
        bytes += entry.object().unwrap().data.len();
    }
    println!("manifest at tags  : {:>6} ms  ({} bytes)", started.elapsed().as_millis(), bytes);

    // 3. the history with the paths each commit changed
    let started = Instant::now();
    let head = repo.head_id().unwrap().detach();
    let walk = repo
        .rev_walk([head])
        .sorting(gix::revision::walk::Sorting::BreadthFirst)
        .all()
        .unwrap();
    let mut commits = 0usize;
    let mut paths = 0usize;
    let mut cache = repo.diff_resource_cache_for_tree_diff().unwrap();
    let _ = &mut cache;
    for info in walk {
        let info = info.unwrap();
        let commit = repo.find_commit(info.id).unwrap();
        let tree = commit.tree().unwrap();
        let parent_tree = match commit.parent_ids().next() {
            Some(parent) => repo.find_commit(parent).unwrap().tree().unwrap(),
            None => repo.empty_tree(),
        };
        let mut platform = parent_tree.changes().unwrap();
        platform.options(|options| {
            options.track_rewrites(None);
        });
        platform
            .for_each_to_obtain_tree(&tree, |change| {
                let _ = change.location();
                paths += 1;
                Ok::<_, std::convert::Infallible>(std::ops::ControlFlow::Continue(()))
            })
            .unwrap();
        commits += 1;
    }
