//! Reads through gix, answering what the `git` binary would without a process per question.
//!
//! Every function returns `None` for anything it cannot answer exactly as `git` would, and the caller then asks `git`.
//! Writes, signing and trust checks never come here.

use std::collections::{BTreeSet, HashMap};
use std::path::{Path, PathBuf};

use gix::diff::tree::recorder::Change;
use gix::prelude::FindExt;

use crate::{CommitSha, TagName};

/// A repository opened for native reads, at the root of its work tree.
pub(super) struct NativeRepo {
    repo: gix::Repository,
}

/// One commit of a history read: its id, its parents' ids and the paths it changed.
pub(super) struct HistoryRecord {
    pub sha: String,
    pub parents: Vec<String>,
    pub paths: Vec<PathBuf>,
}

impl NativeRepo {
    /// `None` when `CALLISTO_GIT_BACKEND=system` asks for the binary, or when `root` is not exactly the root of the work
    /// tree of a complete repository, which is all the native reads are written for.
    pub(super) fn open(root: &Path) -> Option<Self> {
        if std::env::var_os("CALLISTO_GIT_BACKEND").is_some_and(|backend| backend == "system") {
            return None;
        }
        let repo = gix::open(root).ok()?;
        if dunce::canonicalize(repo.workdir()?).ok()? != dunce::canonicalize(root).ok()? || repo.is_shallow() {
            return None;
        }
        Some(NativeRepo { repo })
    }

    /// Every tag with the commit it ends at, `None` for the commit when it ends at something else.
    pub(super) fn tags_with_commits(&self) -> Option<Vec<(TagName, Option<CommitSha>)>> {
        let mut tags = Vec::new();
        for reference in self.repo.references().ok()?.tags().ok()? {
            let mut reference = reference.ok()?;
            let Ok(name) = TagName::parse(&reference.name().shorten().to_string()) else {
                continue;
            };
            let commit = reference.peel_to_id().ok().and_then(|id| {
                let id = id.detach();
                let is_commit = self.repo.find_header(id).ok()?.kind() == gix::object::Kind::Commit;
                is_commit.then(|| CommitSha::parse(&id.to_string()).ok()).flatten()
            });
            tags.push((name, commit));
        }
        Some(tags)
    }

    /// The text of each `(revision, path)`, lossily decoded, `None` for a path or revision that does not exist.
    pub(super) fn read_blobs(&self, wanted: &[(String, PathBuf)]) -> Option<Vec<Option<String>>> {
        wanted.iter().map(|(rev, path)| self.blob_at(rev, path)).collect()
    }

    fn blob_at(&self, rev: &str, path: &Path) -> Option<Option<String>> {
        let Ok(id) = self.repo.rev_parse_single(rev) else {
            return Some(None);
        };
        let tree = id.object().ok()?.peel_to_commit().ok()?.tree().ok()?;
        let Some(entry) = tree.lookup_entry_by_path(path).ok()? else {
            return Some(None);
        };
        if !entry.mode().is_blob() {
            return None;
        }
        let object = entry.object().ok()?;
        Some(Some(String::from_utf8_lossy(&object.data).into_owned()))
    }

    /// `HEAD` and every boundary back to their common ancestor, children before parents, each with the paths it changed.
    /// A merge commit lists the paths where it differs from every parent.
    pub(super) fn history(&self, head: &CommitSha, boundaries: &[CommitSha]) -> Option<Vec<HistoryRecord>> {
        let id_of = |sha: &CommitSha| gix::ObjectId::from_hex(sha.as_str().as_bytes()).ok();
        let tips: Vec<gix::ObjectId> = std::iter::once(head).chain(boundaries).map(id_of).collect::<Option<_>>()?;
        let base = if boundaries.is_empty() {
            None
        } else {
            let ids: Vec<gix::ObjectId> = boundaries.iter().map(id_of).collect::<Option<_>>()?;
            self.repo.merge_base_octopus(ids).ok().map(|id| id.detach())
        };

        let mut walk = self.repo.rev_walk(tips.clone());
        if let Some(base) = base {
            walk = walk.with_hidden([base]);
        }
        let walk = walk.sorting(gix::revision::walk::Sorting::BreadthFirst).all().ok()?;

        let objects = &self.repo.objects;
        let (mut commit_buf, mut lhs_buf, mut rhs_buf) = (Vec::new(), Vec::new(), Vec::new());
        let mut state = gix::diff::tree::State::default();
        let mut recorder = gix::diff::tree::Recorder::default();
        let mut records = Vec::new();
        for info in walk {
            let info = info.ok()?;
            let tree = objects.find_commit_iter(&info.id, &mut commit_buf).ok()?.tree_id().ok()?;
            let mut changed: Option<BTreeSet<PathBuf>> = None;
            let parents: Vec<Option<gix::ObjectId>> = if info.parent_ids.is_empty() {
                vec![None]
            } else {
                info.parent_ids.iter().map(|parent| Some(*parent)).collect()
            };
            for parent in &parents {
                let parent_tree = match parent {
                    Some(parent) => Some(objects.find_commit_iter(parent, &mut commit_buf).ok()?.tree_id().ok()?),
                    None => None,
                };
                let rhs = objects.find_tree_iter(&tree, &mut rhs_buf).ok()?;
                let lhs = match &parent_tree {
                    Some(parent_tree) => objects.find_tree_iter(parent_tree, &mut lhs_buf).ok()?,
                    None => gix::objs::TreeRefIter::from_bytes(&[], self.repo.object_hash()),
                };
                recorder.records.clear();
                gix::diff::tree(lhs, rhs, &mut state, objects, &mut recorder).ok()?;
                let against_parent: BTreeSet<PathBuf> = recorder
                    .records
                    .iter()
                    .filter_map(|change| {
                        let (Change::Addition { entry_mode, path, .. }
                        | Change::Deletion { entry_mode, path, .. }
                        | Change::Modification { entry_mode, path, .. }) = change;
                        (!entry_mode.is_tree()).then(|| gix::path::from_bstr(path.as_ref()).into_owned())
                    })
                    .collect();
                changed = Some(match changed {
                    None => against_parent,
                    Some(so_far) => so_far.intersection(&against_parent).cloned().collect(),
                });
            }
            records.push(HistoryRecord {
                sha: info.id.to_string(),
                parents: info.parent_ids.iter().map(ToString::to_string).collect(),
                paths: changed.unwrap_or_default().into_iter().collect(),
            });
        }
        Some(children_first(records, &tips))
    }
}

/// Orders `records` so every commit comes before its parents, as `git log --topo-order` does. Parents that are not
/// listed are ignored.
fn children_first(records: Vec<HistoryRecord>, tips: &[gix::ObjectId]) -> Vec<HistoryRecord> {
    let index: HashMap<&str, usize> = records
        .iter()
        .enumerate()
        .map(|(position, record)| (record.sha.as_str(), position))
        .collect();
    let mut visited = vec![false; records.len()];
    let mut finished = Vec::with_capacity(records.len());
    let roots = tips
        .iter()
        .filter_map(|tip| index.get(tip.to_string().as_str()).copied())
        .chain(0..records.len());
    for root in roots {
        if visited[root] {
            continue;
        }
        visited[root] = true;
        let mut stack = vec![(root, 0usize)];
        while let Some((commit, next_parent)) = stack.pop() {
            match records[commit].parents.get(next_parent) {
                Some(parent) => {
                    stack.push((commit, next_parent + 1));
                    if let Some(&parent) = index.get(parent.as_str()) {
                        if !visited[parent] {
                            visited[parent] = true;
                            stack.push((parent, 0));
                        }
                    }
                }
                None => finished.push(commit),
            }
        }
    }
    // Postorder puts parents first; reversed, children come first.
    let mut by_position: Vec<Option<HistoryRecord>> = records.into_iter().map(Some).collect();
    finished
        .into_iter()
        .rev()
        .filter_map(|position| by_position[position].take())
        .collect()
}

