use std::sync::atomic::{AtomicU64, Ordering::Relaxed};
use std::sync::Arc;
use std::time::Instant;

use gix::odb::pack::cache::DecodeEntry;
use gix::prelude::FindExt;

#[derive(Default)]
struct Counters {
    gets: AtomicU64,
    hits: AtomicU64,
    puts: AtomicU64,
    put_bytes: AtomicU64,
    hit_bytes: AtomicU64,
}

struct Counting {
    inner: gix::odb::pack::cache::lru::MemoryCappedHashmap,
    counters: Arc<Counters>,
}

impl DecodeEntry for Counting {
    fn put(&mut self, pack_id: u32, offset: u64, data: &[u8], kind: gix::object::Kind, compressed_size: usize) {
        self.counters.puts.fetch_add(1, Relaxed);
        self.counters.put_bytes.fetch_add(data.len() as u64, Relaxed);
        self.inner.put(pack_id, offset, data, kind, compressed_size);
    }

    fn get(&mut self, pack_id: u32, offset: u64, out: &mut Vec<u8>) -> Option<(gix::object::Kind, usize)> {
        self.counters.gets.fetch_add(1, Relaxed);
        let found = self.inner.get(pack_id, offset, out);
        if found.is_some() {
            self.counters.hits.fetch_add(1, Relaxed);
            self.counters.hit_bytes.fetch_add(out.len() as u64, Relaxed);
        }
        found
    }
}

fn main() {
    let path = std::env::args().nth(1).expect("repo path");
    let cap: usize = std::env::args().nth(2).expect("cache bytes").parse().expect("number");
    let mut repo = gix::open(&path).expect("open");
    let counters = Arc::new(Counters::default());
    let shared = counters.clone();
    repo.objects.set_pack_cache(move || {
        Box::new(Counting {
            inner: gix::odb::pack::cache::lru::MemoryCappedHashmap::new(cap),
            counters: shared.clone(),
        })
    });
    repo.objects.unset_object_cache();

    let started = Instant::now();
    let head = repo.head_id().unwrap().detach();
    let walk = repo
        .rev_walk([head])
        .sorting(gix::revision::walk::Sorting::BreadthFirst)
        .all()
        .unwrap();
    let objects = &repo.objects;
    let (mut commit_buf, mut parent_buf, mut lhs_buf, mut rhs_buf) = (Vec::new(), Vec::new(), Vec::new(), Vec::new());
    let mut state = gix::diff::tree::State::default();
    let mut recorder = gix::diff::tree::Recorder::default();
    let kind = repo.object_hash();
    let mut commits = 0usize;
    for info in walk {
        let info = info.unwrap();
        let tree_id = objects.find_commit_iter(&info.id, &mut commit_buf).unwrap().tree_id().unwrap();
        let rhs = objects.find_tree_iter(&tree_id, &mut rhs_buf).unwrap();
        let lhs = match info.parent_ids.first() {
            Some(parent) => {
                let parent_tree = objects.find_commit_iter(parent, &mut parent_buf).unwrap().tree_id().unwrap();
                objects.find_tree_iter(&parent_tree, &mut lhs_buf).unwrap()
            }
            None => gix::objs::TreeRefIter::from_bytes(&[], kind),
        };
        recorder.records.clear();
        gix::diff::tree(lhs, rhs, &mut state, objects, &mut recorder).unwrap();
        commits += 1;
    }
    let (gets, hits) = (counters.gets.load(Relaxed), counters.hits.load(Relaxed));
    println!(
        "cap {:>5} MB: {:>6} ms  {commits} commits | gets {gets}  hits {hits} ({:.0}%)  puts {}  MB put {}  MB served from cache {}",
        cap / (1024 * 1024),
        started.elapsed().as_millis(),
        100.0 * hits as f64 / gets.max(1) as f64,
        counters.puts.load(Relaxed),
        counters.put_bytes.load(Relaxed) / (1024 * 1024),
        counters.hit_bytes.load(Relaxed) / (1024 * 1024),
    );
}

