                lines.len(),
                specs.len()
            )));
        }
        specs
            .iter()
            .zip(lines)
            .map(|(spec, line)| {
                if line.strip_prefix(spec.as_str()) == Some(" missing") {
                    return Ok(None);
                }
                match line.split(' ').next() {
                    Some(id) if CommitSha::parse(id).is_ok() => Ok(Some(id.to_owned())),
                    _ => Err(malformed(format!("`{spec}` was answered with `{line}`"))),
