11	/// When a [`poll_step`] checks: at once, then after each delay in turn, then at a fixed interval. Each delay counts
12	/// from the end of the previous check.
13	#[derive(Debug, Clone, PartialEq, Eq)]
14	pub struct PollSchedule {
15	    delays: Vec<Duration>,
16	    then_every: Duration,
17	}
18	
19	impl Default for PollSchedule {
20	    /// 2 s, 4 s, 8 s and 16 s, then every 30 s: quick for something that lands fast, gentle on a slow registry.
21	    fn default() -> Self {
22	        Self::new([2, 4, 8, 16].map(Duration::from_secs), Duration::from_secs(30))
23	    }
24	}
25	
26	impl PollSchedule {
27	    /// Waits `delays` in turn between the first checks, then `then_every` between every later one. A zero delay is
28	    /// floored to 1 ms so a poll can never spin.
29	    #[must_use]
30	    pub fn new(delays: impl IntoIterator<Item = Duration>, then_every: Duration) -> Self {
31	        Self { delays: delays.into_iter().map(floor).collect(), then_every: floor(then_every) }
32	    }
33	
34	    /// The same delay between every check. Zero is floored to 1 ms.
35	    #[must_use]
36	    pub fn every(interval: Duration) -> Self {
37	        Self::new([], interval)
38	    }
39	
40	    /// The wait after check `n` (0-based) before the next one.
41	    #[must_use]
42	    pub fn delay_after(&self, n: usize) -> Duration {
43	        self.delays.get(n).copied().unwrap_or(self.then_every)
44	    }
45	}
46	
47	fn floor(d: Duration) -> Duration {
48	    d.max(Duration::from_millis(1))
49	}
