100	impl<F, Fut> Step for PollStep<F>
101	where
102	    F: Fn(StepContext) -> Fut + Send + Sync,
103	    Fut: Future<Output = Result<Readiness, ExecutionError>> + Send + 'static,
104	{
105	    fn run<'a>(&'a self, ctx: &'a StepContext) -> StepFuture<'a> {
106	        Box::pin(self.poll(ctx))
107	    }
108	
109	    fn replay(&self) -> Replay {
110	        Replay::Idempotent
111	    }
112	
113	    fn attempt_bound(&self) -> AttemptBound {
114	        AttemptBound::Deadline
115	    }
116	}
117	
118	impl<F, Fut> PollStep<F>
119	where
120	    F: Fn(StepContext) -> Fut + Send + Sync,
121	    Fut: Future<Output = Result<Readiness, ExecutionError>> + Send + 'static,
122	{
123	    async fn poll(&self, ctx: &StepContext) -> Result<(), ExecutionError> {
124	        let started = Instant::now();
125	        let bound = ctx.attempt_deadline().or(ctx.deadline());
126	        let token = ctx.cancellation();
127	        let mut checks = 0usize;
128	        loop {
129	            let limit = match bound {
130	                Some(end) => ctx.attempt_timeout().min(end.saturating_duration_since(Instant::now())),
131	                None => ctx.attempt_timeout(),
132	            };
133	            let answer = tokio::select! {
134	                biased;
135	                () = token.cancelled() => return Err(ExecutionError::Cancelled),
136	                answer = tokio::time::timeout(limit, (self.check)(ctx.clone())) => answer,
137	            };
138	            checks = checks.saturating_add(1);
139	            let last = match answer {
140	                Ok(Ok(Readiness::Ready)) => return Ok(()),
141	                Ok(Ok(Readiness::NotYet(seen))) => seen,
142	                Ok(Err(err)) if err.is_retryable() => format!("the check failed: {err}"),
143	                Ok(Err(err)) => return Err(err),
144	                Err(_) => format!("the check timed out after {}ms", millis(limit)),
145	            };
146	            let wait = self.schedule.delay_after(checks - 1);
147	            let stop = match bound {
148	                Some(end) => Instant::now().checked_add(wait).is_none_or(|wake| wake >= end),
149	                None => false,
150	            };
151	            if stop {
152	                let mut message = String::with_capacity(96 + last.len());
153	                message.push_str("not ready after ");
154	                message.push_str(&checks.to_string());
155	                message.push_str(if checks == 1 { " check" } else { " checks" });
156	                message.push_str(" over ");
157	                message.push_str(&millis(started.elapsed()).to_string());
158	                message.push_str("ms, and the next check would fall past the deadline; last observed: ");
159	                message.push_str(&last);
160	                return Err(ExecutionError::DeadlinePassed { message });
161	            }
162	            tokio::select! {
163	                biased;
164	                () = token.cancelled() => return Err(ExecutionError::Cancelled),
165	                () = tokio::time::sleep(wait) => {}
166	            }
167	        }
168	    }
169	}
