//! Git access by shelling the real `git` binary through a
//! [`crate::CommandRunner`].

use std::path::{Path, PathBuf};

use crate::{ApplyPermit, CommandOutput, CommandRunner, CommitSha, StagedChangeKindV1, StagedChangeV1, TagName};

