/// Replaces `pkg-a@1.0.0` with an annotated tag carrying `message`, or a lightweight one when there is none.
fn retag(root: &Path, message: Option<&str>) {
    match message {
        Some(message) => run_git(root, &["tag", "-f", "-a", "-m", message, "pkg-a@1.0.0"]),
