253	fn validate_operations(operations: &[ReleaseOperation]) -> Result<(), ReleaseIntentError> {
254	    let mut ids = BTreeSet::new();
255	    for operation in operations {
256	        if !ids.insert(operation.id.clone()) {
257	            return Err(ReleaseIntentError::DuplicateOperation {
258	                id: Box::new(operation.id.clone()),
259	            });
260	        }
261	    }
262	    for operation in operations {
263	        if operation.prerequisites.windows(2).any(|pair| pair[0] >= pair[1]) {
264	            return Err(ReleaseIntentError::NonCanonicalPrerequisiteOrder {
265	                id: Box::new(operation.id.clone()),
266	            });
267	        }
268	        for prerequisite in &operation.prerequisites {
269	            if prerequisite == &operation.id {
270	                return Err(ReleaseIntentError::SelfPrerequisite {
271	                    id: Box::new(operation.id.clone()),
272	                });
273	            }
274	            if !ids.contains(prerequisite) {
275	                return Err(ReleaseIntentError::UnknownPrerequisite {
276	                    id: Box::new(operation.id.clone()),
277	                    prerequisite: Box::new(prerequisite.clone()),
278	                });
279	            }
280	        }
281	    }
282	    let canonical = canonical_operation_order(
283	        operations
284	            .iter()
285	            .map(|operation| (operation.id.clone(), operation.prerequisites.clone())),
286	    )?;
287	    if operations.iter().map(ReleaseOperation::id).ne(canonical.iter()) {
288	        return Err(ReleaseIntentError::NonCanonicalOperationOrder);
289	    }
290	    Ok(())
291	}
