293	/// The canonical order of release operations: the smallest topological order by operation id, so the same operations
294	/// always order the same way. Each operation comes with its prerequisites.
295	///
296	/// # Errors
297	///
298	/// The first problem found, in this order: a repeated operation, a prerequisite that is no operation, an operation
299	/// that is its own prerequisite, then a cycle, named by one operation on it.
300	pub fn canonical_operation_order(
301	    operations: impl IntoIterator<Item = (ReleaseOperationId, Vec<ReleaseOperationId>)>,
302	) -> Result<Vec<ReleaseOperationId>, ReleaseIntentError> {
303	    let dag = Dag::from_nodes(operations, Order::Key).map_err(|violations| {
304	        let first = violations.into_iter().find_map(|violation| match violation {
305	            Violation::DuplicateNode { key } => Some(ReleaseIntentError::DuplicateOperation { id: Box::new(key) }),
306	            Violation::UnknownDependency {
307	                dependent,
308	                prerequisite,
309	            } => Some(ReleaseIntentError::UnknownPrerequisite {
310	                id: Box::new(dependent),
311	                prerequisite: Box::new(prerequisite),
312	            }),
313	            Violation::SelfDependency { key } => Some(ReleaseIntentError::SelfPrerequisite { id: Box::new(key) }),
314	            Violation::Cycle(cycle) => cycle.members().first().map(|id| ReleaseIntentError::Cycle {
315	                id: Box::new(id.clone()),
316	            }),
317	            _ => None,
318	        });
319	        // Only a graph too large to hold in memory reports nothing above.
320	        first.unwrap_or(ReleaseIntentError::NonCanonicalOperationOrder)
321	    })?;
322	    Ok(dag.keys_in_order().cloned().collect())
323	}
