263	/// The pending operations that may start, in the intent's canonical order.
264	///
265	/// An operation may start when every one of its transitive prerequisites is `Published` or `AlreadySatisfied`. A
266	/// registry publish may also follow a registry publish that is only `issued`: npm takes a package whose dependency is
267	/// not visible yet, and everything announced (tag, release, uploads, publication) still waits for the version to be
268	/// shown. `ready` checks direct prerequisites; the ancestor check keeps a defective executor that recorded a later
269	/// operation's success before its prerequisite from making anything behind it eligible.
270	pub(crate) fn eligible_in(
271	    dag: &Dag<ReleaseOperationId>,
272	    state: &ReleaseExecutionStateV1,
273	    issued: &BTreeSet<ReleaseOperationId>,
274	) -> Vec<ReleaseOperationId> {
275	    let succeeded = |id: &ReleaseOperationId| state.operation_state(id).is_some_and(OperationState::is_success);
276	    dag.ready(
277	        |id| succeeded(id) || issued.contains(id),
278	        |id| state.operation_state(id) == Some(OperationState::Pending),
279	    )
280	    .filter_map(|ix| dag.key(ix).map(|id| (ix, id)))
281	    .filter(|(ix, id)| {
282	        dag.ancestors(&[*ix]).into_iter().all(|ancestor| {
283	            dag.key(ancestor).is_some_and(|prerequisite| {
284	                succeeded(prerequisite)
285	                    || (issued.contains(prerequisite) && is_registry_effect(id) && is_registry_effect(prerequisite))
286	            })
287	        })
288	    })
289	    .map(|(_, id)| id.clone())
290	    .collect()
291	}
