/// How long a version this run just published may take to appear on its registry's read path.
///
/// Sized to the cache lifetime of the read the observation uses, plus a minute of slack: npm serves a package's
/// document with `max-age=300` (a missing package's 404 too), so a read that primed the cache just before the publish
/// can answer stale for up to five minutes. `cargo publish` waits for the index itself.
pub(crate) fn default_visibility_window(ecosystem: callisto_model::Ecosystem) -> Duration {
    match ecosystem {
        callisto_model::Ecosystem::Npm | callisto_model::Ecosystem::Pypi => Duration::from_secs(360),
        _ => Duration::from_secs(120),
    }
}

/// The waits between looks at a version that is not yet visible: 15s, 45s, 2m, then 3m steps.
///
/// A look is the first thing done after the publishes are issued, so a registry that purges its cache shows the
/// version at once, and the earlier packages of a release have aged by the time the last is looked at. What is left
/// is a stale cache that expires on its own, up to five minutes after it was filled, so the looks are spaced to catch
/// that, not to poll: five looks cover the default six-minute window.
pub(crate) fn visibility_backoff(attempt: u32) -> Duration {
    const STEPS: [u64; 3] = [15, 45, 120];
    const LAST_STEP: u64 = 180;
    Duration::from_secs(
        usize::try_from(attempt)
            .ok()
            .and_then(|index| STEPS.get(index))
            .copied()
            .unwrap_or(LAST_STEP),
    )
}

/// Retries `attempt` while it reports `Transient`, until `window` of waiting is spent; the last answer is then reported.
///
/// Unlike [`retry_observation`] the bound is time, not tries: how long a registry lags is a property of the registry,
/// not of how many times it was asked.
pub(crate) fn retry_within_window<T>(
    sleeper: &dyn Sleeper,
    window: Duration,
    mut attempt: impl FnMut() -> Result<Attempt<T>, GraphError>,
) -> Result<T, GraphError> {
    let mut waited = Duration::ZERO;
    let mut index = 0;
    loop {
        match attempt()? {
            Attempt::Settled(value) => return Ok(value),
            Attempt::Transient { value, retry_after } => {
                let remaining = window.saturating_sub(waited);
                if remaining.is_zero() {
                    return Ok(value);
                }
                let wait = retry_after
                    .unwrap_or_else(|| visibility_backoff(index))
                    .clamp(Duration::from_secs(1), OBSERVATION_BACKOFF_CAP)
                    .min(remaining);
                sleeper.sleep(wait);
                waited += wait;
                index += 1;
            }
        }
    }
}

//! Raw HTTP response parsing for the forge lookups that go through
//! `gh api --include`.
//!
//! The response is kept whole -- status line, headers, body -- because the
//! retry policy needs `Retry-After` and the rate-limit headers, and the
//! classifier needs the exact status.

use std::time::{Duration, SystemTime, UNIX_EPOCH};

/// One parsed HTTP response.
#[derive(Clone, Debug, PartialEq, Eq)]
pub(crate) struct HttpResponse {
    pub(crate) status: u16,
    pub(crate) headers: Vec<(String, String)>,
    pub(crate) body: String,
}

impl HttpResponse {
    pub(crate) fn header(&self, name: &str) -> Option<&str> {
        self.headers
            .iter()
            .find(|(key, _)| key.eq_ignore_ascii_case(name))
            .map(|(_, value)| value.as_str())
    }

    /// The server's own wait instruction, in delta-seconds or as an HTTP-date.
    pub(crate) fn retry_after(&self) -> Option<Duration> {
        parse_retry_after(self.header("retry-after")?, now_unix_seconds())
    }

    /// Whether a 403 is a rate-limit refusal rather than a real authorization
    /// failure; only the former may be retried.
    pub(crate) fn is_rate_limited(&self) -> bool {
        self.header("retry-after").is_some()
            || self
                .header("x-ratelimit-remaining")
                .is_some_and(|value| value.trim() == "0")
    }

    /// A rate limit or server error may resolve on its own, unlike a client error or malformed body. Shared by
    /// every status-reading provider (`gh api`, PyPI) so they can't drift on which statuses retry.
    pub(crate) fn is_transient(&self) -> bool {
        matches!(self.status, 429 | 500..=599) || (self.status == 403 && self.is_rate_limited())
    }
}

fn now_unix_seconds() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map_or(0, |elapsed| elapsed.as_secs())
}

/// Parses a raw `gh api --include` response. The last header block wins, so an
/// interim `100 Continue` or a proxy preamble cannot be mistaken for the real
/// status.
pub(crate) fn parse_http_response(raw: &str) -> Result<HttpResponse, String> {
    let (headers, body) = raw
        .rsplit_once("\r\n\r\n")
        .or_else(|| raw.rsplit_once("\n\n"))
        .ok_or_else(|| "response has no blank line separating headers from body".to_owned())?;

