    let dir = repo(&[
        ("Cargo.toml", "[workspace]\nmembers = [\"core\", \"other\"]\n"),
        (
            "core/Cargo.toml",
            "[package]\nname = \"core\"\nversion = \"1.0.0\"\nedition = \"2021\"\n",
        ),
