313	fn collect_answers(
314	    args: &InitArgs,
315	    facts: &InitFacts,
316	    prompting: bool,
317	    prompter: &mut dyn Prompter,
318	) -> Result<InitAnswers, CliError> {
319	    let versioning = match args.versioning {
320	        Some(InitVersioning::Fixed) => Versioning::Fixed,
321	        Some(InitVersioning::Independent) => Versioning::Independent,
322	        None if prompting => {
323	            let choices: Vec<String> = VERSIONING_CHOICES.iter().map(|choice| (*choice).to_owned()).collect();
324	            match prompter.select(VERSIONING_PROMPT, &choices)? {
325	                0 => Versioning::Independent,
326	                _ => Versioning::Fixed,
327	            }
328	        }
329	        None => return Err(missing("--versioning")),
330	    };
331	    let no_binaries = InitAnswers {
332	        versioning,
333	        binaries: None,
334	    };
335	
336	    let binaries: Vec<&InitPackage> = facts.binary_packages().collect();
337	    if binaries.is_empty() && !args.artifact_targets.is_empty() {
338	        if let Some(package) = facts.unsupported_artifact_packages().next() {
339	            return Err(GraphError::InitUnsupportedArtifactBuilder {
340	                package: package.id.clone(),
341	                ecosystem: package
342	                    .id
343	                    .split_once('/')
344	                    .map_or("unknown", |(ecosystem, _)| ecosystem)
345	                    .to_owned(),
346	            }
347	            .into());
348	        }
349	        return Err(GraphError::InitNoBinaryPackage.into());
350	    }
351	    let requested_product = args
352	        .product_package
353	        .as_deref()
354	        .map(|name| facts.product_package(name))
355	        .transpose()?;
356	    if binaries.is_empty() {
357	        return Ok(no_binaries);
358	    }
359	    // No `origin`: the forge question below has nothing to validate a repository against, so
360	    // shipping is never offered (skips straight to `no_binaries`); `--artifact-target` without
361	    // `origin` is already rejected up front in `run`.
362	    let ship = !args.artifact_targets.is_empty()
363	        || (facts.origin.is_some() && prompting && prompter.confirm(SHIP_PROMPT, false)?);
364	    if !ship {
365	        return Ok(no_binaries);
366	    }
367	
368	    let product = match (requested_product, binaries.as_slice()) {
369	        (Some(product), _) => product,
370	        (None, [only]) => only,
371	        (None, _) if prompting => {
372	            let ids: Vec<String> = binaries.iter().map(|package| package.id.clone()).collect();
373	            binaries[prompter.select(PRODUCT_PROMPT, &ids)?]
374	        }
375	        (None, _) => return Err(missing("--product-package")),
376	    };
377	
378	    let forge_repository = match &args.forge_repository {
379	        Some(value) => scaffold::forge_repository(facts, value)?,
380	        None if prompting => {
381	            let detected = facts.origin_repository.as_ref().map(|repository| repository.as_slug());
382	            scaffold::forge_repository(facts, &prompter.input(FORGE_PROMPT, detected.as_deref())?)?
383	        }
384	        None => return Err(missing("--forge-repository")),
385	    };
386	
387	    let targets = if args.artifact_targets.is_empty() {
388	        loop {
389	            let answer = prompter.input(TARGETS_PROMPT, None)?;
390	            let targets: Vec<String> = answer.split(',').map(str::trim).map(str::to_owned).collect();
391	            if targets.iter().all(|target| target.is_empty()) {
392	                // Nothing meaningful submitted: re-ask rather than error.
393	                continue;
394	            }
395	            break targets;
396	        }
397	    } else {
398	        args.artifact_targets.clone()
399	    };
400	    let targets = scaffold::validate_targets(&targets)?;
401	
402	    Ok(InitAnswers {
403	        versioning,
404	        binaries: Some(BinaryRelease {
405	            product: product.id.clone(),
406	            forge_repository,
407	            targets,
408	        }),
409	    })
410	}
