    assert_eq!(differing_repositories(Some("git+https://github.com/example/single"), origin), None);
    assert_eq!(differing_repositories(None, origin), None);
    assert_eq!(differing_repositories(Some("not a url"), origin), None);
    assert_eq!(differing_repositories(Some("https://github.com/a/b"), "/tmp/local/remote.git"), None);
}

